#include "common.h"
#include <cstring>
#include <cmath>
#include <sstream>
#include <iomanip>
#include <cerrno>
#include <unistd.h>

OutBuf g_out;

OutBuf::OutBuf() : _unbuf(false) { _buf.reserve(1 << 16); }
void OutBuf::write(const std::string& s) {
    _buf.append(s);
    if (_unbuf || _buf.size() >= 14745) flush();
}
void OutBuf::write(const char* s) {
    _buf.append(s);
    if (_unbuf || _buf.size() >= 14745) flush();
}
void OutBuf::write(char c) {
    _buf.push_back(c);
    if (_unbuf || _buf.size() >= 14745) flush();
}
void OutBuf::flush() {
    if (!_buf.empty()) {
        fwrite(_buf.data(), 1, _buf.size(), stdout);
        _buf.clear();
    }
    fflush(stdout);
}
OutBuf::~OutBuf() { flush(); }

void splitTabs(const std::string& line, std::vector<std::string>& out) {
    out.clear();
    size_t start = 0;
    while (true) {
        size_t p = line.find('\t', start);
        if (p == std::string::npos) {
            out.push_back(line.substr(start));
            break;
        }
        out.push_back(line.substr(start, p - start));
        start = p + 1;
    }
}

void splitOn(const std::string& s, char delim, std::vector<std::string>& out) {
    out.clear();
    size_t start = 0;
    while (true) {
        size_t p = s.find(delim, start);
        if (p == std::string::npos) {
            out.push_back(s.substr(start));
            break;
        }
        out.push_back(s.substr(start, p - start));
        start = p + 1;
    }
}

bool isInteger(const std::string& s) {
    if (s.empty()) return false;
    size_t i = 0;
    if (s[0] == '-' || s[0] == '+') i = 1;
    if (i >= s.size()) return false;
    for (; i < s.size(); i++)
        if (s[i] < '0' || s[i] > '9') return false;
    return true;
}

bool isNumericStr(const std::string& s) {
    if (s.empty()) return false;
    char* end = nullptr;
    errno = 0;
    strtod(s.c_str(), &end);
    if (end == s.c_str()) return false;
    while (*end == ' ' || *end == '\t') end++;
    return *end == '\0';
}

CHRPOS parseIntStrict(const std::string& s) {
    // Accept optional sign followed by digits only.
    if (!isInteger(s)) {
        fflush(stdout);
        fprintf(stderr, "***** ERROR: illegal number \"%s\". Exiting...\n", s.c_str());
        exit(1);
    }
    return strtoll(s.c_str(), nullptr, 10);
}

double parseDouble(const std::string& s) {
    return strtod(s.c_str(), nullptr);
}

std::string toStr(CHRPOS v) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%lld", v);
    return std::string(buf);
}
std::string toStr(int v) {
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", v);
    return std::string(buf);
}

std::string dblToStr(double v, int prec) {
    std::ostringstream os;
    os << std::setprecision(prec) << v;
    return os.str();
}

bool startsWithNoCase(const std::string& s, const char* prefix) {
    size_t n = strlen(prefix);
    if (s.size() < n) return false;
    for (size_t i = 0; i < n; i++) {
        char a = s[i], b = prefix[i];
        if (a >= 'A' && a <= 'Z') a = a - 'A' + 'a';
        if (b >= 'A' && b <= 'Z') b = b - 'A' + 'a';
        if (a != b) return false;
    }
    return true;
}

std::string joinFields(const std::vector<std::string>& f, size_t from, size_t to, char delim) {
    std::string s;
    for (size_t i = from; i < to && i < f.size(); i++) {
        if (i > from) s.push_back(delim);
        s.append(f[i]);
    }
    return s;
}

void fatal(const std::string& msg) {
    g_out.flush();
    fputs(msg.c_str(), stderr);
    exit(1);
}
void fatalNoFlush(const std::string& msg) {
    fputs(msg.c_str(), stderr);
    exit(1);
}
EOF
