// Record model and file reading with type detection.
#ifndef BT_RECORD_H
#define BT_RECORD_H

#include "common.h"
#include <string>
#include <vector>
#include <memory>

enum FileType {
    FT_UNKNOWN = 0,
    FT_BED3, FT_BED4, FT_BED5, FT_BED6, FT_BED12, FT_BED_PLUS,
    FT_GFF, FT_VCF, FT_BEDPE
};

struct Block { CHRPOS start, end; };

struct Record {
    std::string chrom;
    CHRPOS start = 0;
    CHRPOS end = 0;
    char strand = 0;            // '+', '-', '.', or 0 when the type has no strand column
    std::vector<std::string> f; // original fields
    FileType type = FT_UNKNOWN;
    int fileIdx = 0;            // database index (for multiple -b files)
    long lineNum = 0;
    bool zeroLen = false;       // zero-length record (GFF/VCF/BED start==end)
    // BEDPE second end
    std::string chrom2; CHRPOS start2 = -1, end2 = -1; char strand2 = 0;

    CHRPOS length() const { return end - start; }
    const std::string& name() const;
    const std::string& score() const;
    std::string strandStr() const;
    bool hasStrand() const { return strand == '+' || strand == '-'; }

    // Print the record's fields as in the original file
    void print(std::string& out) const;
    // Print with replaced coordinates (for "overlap" output)
    void printWithCoords(std::string& out, CHRPOS s, CHRPOS e) const;
    // Null record (for -loj / -wao)
    static void printNull(std::string& out, FileType t, int numFields);
    // Split into blocks (BED12) ; otherwise single block
    void getBlocks(std::vector<Block>& blocks, bool split) const;
};

typedef std::shared_ptr<Record> RecordPtr;

// Compressed/uncompressed line reader
class LineReader {
public:
    LineReader();
    ~LineReader();
    bool open(const std::string& fname); // "stdin" or "-" for standard input
    bool getline(std::string& line);
    void close();
    bool isOpen() const { return _open; }
private:
    struct Impl; Impl* _impl;
    bool _open;
};

// Reads records from a BED/GFF/VCF file. Handles headers & type detection.
class RecordFile {
public:
    RecordFile();
    ~RecordFile();
    // Opens and determines the file type. Exits on failure.
    void open(const std::string& fname, int fileIdx = 0);
    // Returns next record (nullptr at EOF)
    RecordPtr next();
    FileType type() const { return _type; }
    int numFields() const { return _numFields; }
    const std::vector<std::string>& header() const { return _header; }
    const std::string& name() const { return _fname; }
    bool isVcf() const { return _type == FT_VCF; }
    bool isGff() const { return _type == FT_GFF; }
    bool isBed() const { return _type >= FT_BED3 && _type <= FT_BED_PLUS; }
    bool parseLine(const std::string& line, Record& r); // false if header/empty
    static bool isHeaderLine(const std::string& line);
    static FileType detectType(const std::vector<std::string>& fields, bool vcfHeader);
    void setBedpe(bool b) { _bedpe = b; }
private:
    LineReader _lr;
    std::string _fname;
    FileType _type;
    int _numFields;
    int _fileIdx;
    std::vector<std::string> _header;
    std::vector<std::string> _pending; // data lines consumed during detection
    size_t _pendingIdx;
    long _lineNum;
    bool _bedpe;
    bool _eof;
    std::vector<std::string> _tok;
    void determineType();
};

// Read whole file into a vector
void readAllRecords(const std::string& fname, std::vector<RecordPtr>& recs, int fileIdx = 0,
                    std::vector<std::string>* header = nullptr, FileType* type = nullptr, int* numFields = nullptr);

#endif
EOF
