#include "record.h"
#include <zlib.h>
#include <cstring>
#include <unistd.h>

static const std::string kDot = ".";
static const std::string kEmpty = "";

// ---------------- Record -----------------
const std::string& Record::name() const {
    switch (type) {
        case FT_BED4: case FT_BED5: case FT_BED6: case FT_BED12: case FT_BED_PLUS:
            return f.size() > 3 ? f[3] : kDot;
        case FT_GFF: return f.size() > 2 ? f[2] : kDot;
        case FT_VCF: return f.size() > 2 ? f[2] : kDot;
        case FT_BEDPE: return f.size() > 6 ? f[6] : kDot;
        default: return kDot;
    }
}
const std::string& Record::score() const {
    switch (type) {
        case FT_BED5: case FT_BED6: case FT_BED12: case FT_BED_PLUS:
            return f.size() > 4 ? f[4] : kDot;
        case FT_GFF: return f.size() > 5 ? f[5] : kDot;
        case FT_VCF: return f.size() > 5 ? f[5] : kDot;
        case FT_BEDPE: return f.size() > 7 ? f[7] : kDot;
        default: return kDot;
    }
}
std::string Record::strandStr() const {
    if (strand == 0) return ".";
    return std::string(1, strand);
}

void Record::print(std::string& out) const {
    if (type == FT_GFF && f.size() > 9) {
        // quirk: 10th field is glued to the 9th
        for (size_t i = 0; i < 9; i++) { if (i) out.push_back('\t'); out.append(f[i]); }
        out.append(f[9]);
        for (size_t i = 10; i < f.size(); i++) { out.push_back('\t'); out.append(f[i]); }
        return;
    }
    for (size_t i = 0; i < f.size(); i++) {
        if (i) out.push_back('\t');
        out.append(f[i]);
    }
}

void Record::printWithCoords(std::string& out, CHRPOS s, CHRPOS e) const {
    std::vector<std::string> g = f;
    if (type == FT_GFF) {
        if (g.size() > 4) { g[3] = toStr(s + 1); g[4] = toStr(e); }
    } else if (type == FT_VCF) {
        if (g.size() > 1) g[1] = toStr(s + 1);
    } else {
        if (g.size() > 2) { g[1] = toStr(s); g[2] = toStr(e); }
    }
    Record tmp; tmp.type = type; tmp.f.swap(g);
    tmp.print(out);
}

void Record::printNull(std::string& out, FileType t, int numFields) {
    switch (t) {
        case FT_BED3: out.append(".\t-1\t-1"); break;
        case FT_BED4: out.append(".\t-1\t-1\t."); break;
        case FT_BED5: out.append(".\t-1\t-1\t.\t-1"); break;
        case FT_BED6: out.append(".\t-1\t-1\t.\t-1\t."); break;
        case FT_BED12: out.append(".\t-1\t-1\t.\t-1\t.\t.\t.\t.\t.\t.\t."); break;
        case FT_BED_PLUS:
            out.append(".\t-1\t-1");
            for (int i = 3; i < numFields; i++) out.append("\t.");
            break;
        case FT_GFF:
            out.append(".\t.\t.\t-1\t-1");
            for (int i = 5; i < numFields; i++) out.append("\t.");
            break;
        case FT_VCF:
            out.append(".\t-1");
            for (int i = 2; i < numFields; i++) out.append("\t.");
            break;
        case FT_BEDPE:
            out.append(".\t-1\t-1\t.\t-1\t-1");
            for (int i = 6; i < numFields; i++) out.append("\t.");
            break;
        default:
            out.append(".\t-1\t-1");
            for (int i = 3; i < numFields; i++) out.append("\t.");
            break;
    }
}

void Record::getBlocks(std::vector<Block>& blocks, bool split) const {
    blocks.clear();
    if (split && type == FT_BED12 && f.size() >= 12) {
        CHRPOS n = parseIntStrict(f[9]);
        std::vector<std::string> sizes, starts;
        splitOn(f[10], ',', sizes);
        splitOn(f[11], ',', starts);
        for (CHRPOS i = 0; i < n; i++) {
            if ((size_t)i >= sizes.size() || (size_t)i >= starts.size()) break;
            if (sizes[i].empty() || starts[i].empty()) break;
            CHRPOS bs = start + parseIntStrict(starts[i]);
            CHRPOS be = bs + parseIntStrict(sizes[i]);
            blocks.push_back({bs, be});
        }
        if (blocks.empty()) blocks.push_back({start, end});
        return;
    }
    blocks.push_back({start, end});
}

// ---------------- LineReader -----------------
struct LineReader::Impl {
    gzFile gz = nullptr;
    char buf[1 << 16];
    size_t pos = 0, len = 0;
    bool eof = false;
};

LineReader::LineReader() : _impl(new Impl()), _open(false) {}
LineReader::~LineReader() { close(); delete _impl; }

bool LineReader::open(const std::string& fname) {
    close();
    if (fname == "stdin" || fname == "-") {
        _impl->gz = gzdopen(dup(0), "rb");
    } else {
        _impl->gz = gzopen(fname.c_str(), "rb");
    }
    if (!_impl->gz) return false;
    gzbuffer(_impl->gz, 1 << 17);
    _impl->pos = _impl->len = 0;
    _impl->eof = false;
    _open = true;
    return true;
}

void LineReader::close() {
    if (_impl->gz) { gzclose(_impl->gz); _impl->gz = nullptr; }
    _open = false;
}

bool LineReader::getline(std::string& line) {
    line.clear();
    if (!_open) return false;
    bool got = false;
    while (true) {
        if (_impl->pos >= _impl->len) {
            if (_impl->eof) break;
            int n = gzread(_impl->gz, _impl->buf, sizeof(_impl->buf));
            if (n <= 0) { _impl->eof = true; break; }
            _impl->pos = 0; _impl->len = (size_t)n;
        }
        char* start = _impl->buf + _impl->pos;
        char* endp = _impl->buf + _impl->len;
        char* nl = (char*)memchr(start, '\n', endp - start);
        if (nl) {
            line.append(start, nl - start);
            _impl->pos = (nl - _impl->buf) + 1;
            got = true;
            break;
        } else {
            line.append(start, endp - start);
            _impl->pos = _impl->len;
            got = true;
        }
    }
    if (!got) return false;
    if (!line.empty() && line.back() == '\r') line.pop_back();
    return true;
}

// ---------------- RecordFile -----------------
RecordFile::RecordFile() : _type(FT_UNKNOWN), _numFields(0), _fileIdx(0), _pendingIdx(0), _lineNum(0), _bedpe(false), _eof(false) {}
RecordFile::~RecordFile() {}

bool RecordFile::isHeaderLine(const std::string& line) {
    if (line.empty()) return true;
    if (line[0] == '#') return true;
    if (startsWithNoCase(line, "track")) return true;
    if (startsWithNoCase(line, "browser")) return true;
    if (startsWithNoCase(line, "visibility")) return true;
    return false;
}

static bool validStrand(const std::string& s) {
    return s == "+" || s == "-" || s == ".";
}

FileType RecordFile::detectType(const std::vector<std::string>& f, bool vcfHeader) {
    size_t n = f.size();
    if (vcfHeader && n >= 2) return FT_VCF;
    if (n >= 3 && isInteger(f[1]) && isInteger(f[2])) {
        if (n == 3) return FT_BED3;
        if (n == 4) return FT_BED4;
        if (n == 5) return FT_BED5;
        if (n == 6) return validStrand(f[5]) ? FT_BED6 : FT_BED_PLUS;
        if (n == 12) {
            if (validStrand(f[5]) && isNumericStr(f[6]) && isNumericStr(f[7]) && isNumericStr(f[9]))
                return FT_BED12;
            return FT_BED_PLUS;
        }
        return FT_BED_PLUS;
    }
    if (n >= 7 && isInteger(f[3]) && isInteger(f[4])) return FT_GFF;
    return FT_UNKNOWN;
}

static void typeError(const std::string& fname) {
    std::string msg = "Error: unable to open file or unable to determine types for file " + fname + "\n\n";
    msg += "- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n";
    msg += "- Also ensure that your file has integer chromosome coordinates in the \n";
    msg += "  expected columns (e.g., cols 2 and 3 for BED).\n";
    fatal(msg);
}

void RecordFile::open(const std::string& fname, int fileIdx) {
    _fname = fname;
    _fileIdx = fileIdx;
    if (!_lr.open(fname)) {
        fatal("Error: Unable to open file " + fname + ". Exiting.\n");
    }
    // when given a regular path that is a directory, gzopen might succeed; check
    determineType();
}

void RecordFile::determineType() {
    std::string line;
    bool vcfHeader = false;
    std::vector<std::string> dataLines;
    while (dataLines.size() < 4 && _lr.getline(line)) {
        _lineNum++;
        if (isHeaderLine(line)) {
            if (line.compare(0, 13, "##fileformat=") == 0 && line.find("VCF") != std::string::npos) vcfHeader = true;
            if (dataLines.empty()) _header.push_back(line);
            else dataLines.push_back(line);  // keep ordering; treated later
            continue;
        }
        dataLines.push_back(line);
    }
    if (_bedpe) {
        _type = FT_BEDPE;
        if (!dataLines.empty()) { splitTabs(dataLines[0], _tok); _numFields = (int)_tok.size(); }
        else _numFields = 10;
        _pending = dataLines; _pendingIdx = 0;
        return;
    }
    if (dataLines.empty()) {
        // Empty file: nothing to detect. Treat as BED3 w/ no records.
        _type = FT_BED3;
        _numFields = 3;
        _eof = true;
        return;
    }
    // type from first data line
    splitTabs(dataLines[0], _tok);
    if (_tok.size() < 3 && !vcfHeader) {
        if (_tok.size() == 2) {
            // mimic original error for 2-field lines containing a numeric field? keep simple
            if (isInteger(_tok[1])) typeError(_fname);
            fatal("Error: Type checker found wrong number of fields while tokenizing data line.\nPerhaps you have extra TAB at the end of your line? Check with \"cat -t\"\n");
        }
        typeError(_fname);
    }
    _type = detectType(_tok, vcfHeader);
    if (_type == FT_UNKNOWN) typeError(_fname);
    _numFields = (int)_tok.size();
    // check consistency of the field counts across the scanned lines
    for (size_t i = 1; i < dataLines.size(); i++) {
        if (isHeaderLine(dataLines[i])) continue;
        splitTabs(dataLines[i], _tok);
        if ((int)_tok.size() != _numFields) {
            fatal("Error: Type checker found wrong number of fields while tokenizing data line.\nPerhaps you have extra TAB at the end of your line? Check with \"cat -t\"\n");
        }
    }
    _pending = dataLines;
    _pendingIdx = 0;
}

bool RecordFile::parseLine(const std::string& line, Record& r) {
    if (isHeaderLine(line)) return false;
    splitTabs(line, r.f);
    r.type = _type;
    r.fileIdx = _fileIdx;
    r.lineNum = _lineNum;
    r.zeroLen = false;
    r.strand = 0;
    if ((int)r.f.size() != _numFields) {
        fatal("Error: line number " + std::to_string(_lineNum) + " of file " + _fname + " has " +
              std::to_string(r.f.size()) + " fields, but " + std::to_string(_numFields) + " were expected.\n");
    }
    const std::vector<std::string>& f = r.f;
    switch (_type) {
        case FT_GFF:
            r.chrom = f[0];
            r.start = parseIntStrict(f[3]) - 1;
            r.end = parseIntStrict(f[4]);
            if (f.size() > 6 && (f[6] == "+" || f[6] == "-" || f[6] == ".")) r.strand = f[6][0];
            else if (f.size() > 6) r.strand = '.';
            break;
        case FT_VCF: {
            r.chrom = f[0];
            r.start = parseIntStrict(f[1]) - 1;
            CHRPOS len = 1;
            if (f.size() > 3) len = (CHRPOS)f[3].size();
            r.end = r.start + len;
            // structural variants: INFO may carry END= or SVLEN=
            if (f.size() > 7) {
                const std::string& info = f[7];
                // look for SVLEN
                size_t p = info.find("SVLEN=");
                if (p != std::string::npos && (p == 0 || info[p-1] == ';')) {
                    CHRPOS svlen = strtoll(info.c_str() + p + 6, nullptr, 10);
                    if (svlen < 0) svlen = -svlen;
                    if (f.size() > 4 && f[4].find('<') != std::string::npos) r.end = r.start + svlen;
                    else if (svlen > 0 && f[4].find('<') != std::string::npos) r.end = r.start + svlen;
                }
                p = info.find("END=");
                if (p != std::string::npos && (p == 0 || info[p-1] == ';')) {
                    CHRPOS e = strtoll(info.c_str() + p + 4, nullptr, 10);
                    if (f.size() > 4 && f[4].find('<') != std::string::npos) r.end = e;
                }
            }
            r.strand = 0;
            break;
        }
        case FT_BEDPE:
            r.chrom = f[0];
            r.start = parseIntStrict(f[1]);
            r.end = parseIntStrict(f[2]);
            r.chrom2 = f[3];
            r.start2 = parseIntStrict(f[4]);
            r.end2 = parseIntStrict(f[5]);
            if (f.size() > 8) r.strand = f[8].empty() ? '.' : f[8][0];
            if (f.size() > 9) r.strand2 = f[9].empty() ? '.' : f[9][0];
            break;
        default:
            r.chrom = f[0];
            r.start = parseIntStrict(f[1]);
            r.end = parseIntStrict(f[2]);
            if (_type == FT_BED6 || _type == FT_BED12) r.strand = f[5][0];
            else if (_type == FT_BED_PLUS && f.size() > 5 && validStrand(f[5])) r.strand = f[5][0];
            break;
    }
    if (_type != FT_BEDPE) {
        if (r.start > r.end || r.start < 0) {
            fatal("Error: Invalid record in file " + _fname + ". Record is \n" + line + "\n");
        }
        if (r.start == r.end) {
            r.zeroLen = true;
        }
    }
    return true;
}

RecordPtr RecordFile::next() {
    std::string line;
    while (true) {
        bool have = false;
        if (_pendingIdx < _pending.size()) {
            line = _pending[_pendingIdx++];
            have = true;
        } else if (!_eof) {
            if (_lr.getline(line)) { _lineNum++; have = true; }
            else _eof = true;
        }
        if (!have) return nullptr;
        RecordPtr r = std::make_shared<Record>();
        if (parseLine(line, *r)) return r;
    }
}

void readAllRecords(const std::string& fname, std::vector<RecordPtr>& recs, int fileIdx,
                    std::vector<std::string>* header, FileType* type, int* numFields) {
    RecordFile rf;
    rf.open(fname, fileIdx);
    if (header) *header = rf.header();
    if (type) *type = rf.type();
    if (numFields) *numFields = rf.numFields();
    RecordPtr r;
    while ((r = rf.next())) recs.push_back(r);
}
