    r.type = _type;
    r.fileIdx = _fileIdx;
    r.lineNum = _lineNum;
    r.zeroLen = false;
    r.strand = 0;
    if ((int)r.f.size() != _numFields) {
        fatal("Error: line number " + std::to_string(_lineNum) + " of file " + _fname + " has " +
              std::to_string(r.f.size()) + " fields, but " + std::to_string(_numFields) + " were expected.\n");
    }
    const std::vector<std::string>& f = r.f;
    switch (_type) {
        case FT_GFF:
            r.chrom = f[0];
            r.start = parseIntStrict(f[3]) - 1;
            r.end = parseIntStrict(f[4]);
            if (f.size() > 6 && (f[6] == "+" || f[6] == "-" || f[6] == ".")) r.strand = f[6][0];
            else if (f.size() > 6) r.strand = '.';
            break;
        case FT_VCF: {
            r.chrom = f[0];
            r.start = parseIntStrict(f[1]) - 1;
            CHRPOS len = 1;
            if (f.size() > 3) len = (CHRPOS)f[3].size();
            r.end = r.start + len;
            // structural variants: INFO may carry END= or SVLEN=
            if (f.size() > 7) {
                const std::string& info = f[7];
                // look for SVLEN
                size_t p = info.find("SVLEN=");
                if (p != std::string::npos && (p == 0 || info[p-1] == ';')) {
                    CHRPOS svlen = strtoll(info.c_str() + p + 6, nullptr, 10);
                    if (svlen < 0) svlen = -svlen;
                    if (f.size() > 4 && f[4].find('<') != std::string::npos) r.end = r.start + svlen;
                    else if (svlen > 0 && f[4].find('<') != std::string::npos) r.end = r.start + svlen;
                }
                p = info.find("END=");
                if (p != std::string::npos && (p == 0 || info[p-1] == ';')) {
                    CHRPOS e = strtoll(info.c_str() + p + 4, nullptr, 10);
                    if (f.size() > 4 && f[4].find('<') != std::string::npos) r.end = e;
                }
            }
            r.strand = 0;
            break;
        }
        case FT_BEDPE:
            r.chrom = f[0];
            r.start = parseIntStrict(f[1]);
            r.end = parseIntStrict(f[2]);
            r.chrom2 = f[3];
            r.start2 = parseIntStrict(f[4]);
            r.end2 = parseIntStrict(f[5]);
            if (f.size() > 8) r.strand = f[8].empty() ? '.' : f[8][0];
            if (f.size() > 9) r.strand2 = f[9].empty() ? '.' : f[9][0];
            break;
        default:
            r.chrom = f[0];
            r.start = parseIntStrict(f[1]);
            r.end = parseIntStrict(f[2]);
            if (_type == FT_BED6 || _type == FT_BED12) r.strand = f[5][0];
            else if (_type == FT_BED_PLUS && f.size() > 5 && validStrand(f[5])) r.strand = f[5][0];
            break;
    }
    if (_type != FT_BEDPE) {
        if (r.start > r.end || r.start < 0) {
            fatal("Error: Invalid record in file " + _fname + ". Record is \n" + line + "\n");
        }
        if (r.start == r.end) {
            r.zeroLen = true;
        }
    }
    return true;
}

RecordPtr RecordFile::next() {
    std::string line;
    while (true) {
        bool have = false;
        if (_pendingIdx < _pending.size()) {
            line = _pending[_pendingIdx++];
            have = true;
        } else if (!_eof) {
            if (_lr.getline(line)) { _lineNum++; have = true; }
            else _eof = true;
        }
        if (!have) return nullptr;
        RecordPtr r = std::make_shared<Record>();
        if (parseLine(line, *r)) return r;
    }
}

void readAllRecords(const std::string& fname, std::vector<RecordPtr>& recs, int fileIdx,
                    std::vector<std::string>* header, FileType* type, int* numFields) {
    RecordFile rf;
    rf.open(fname, fileIdx);
    if (header) *header = rf.header();
    if (type) *type = rf.type();
    if (numFields) *numFields = rf.numFields();
    RecordPtr r;
    while ((r = rf.next())) recs.push_back(r);
}
