void GenomeFile::load(const std::string& fname) {
    _fname = fname;
    LineReader lr;
    if (!lr.open(fname)) {
        fatal("Error: The requested genome file (" + fname + ") could not be opened. Exiting!\n");
    }
    std::string line;
    std::vector<std::string> tok;
    while (lr.getline(line)) {
