        splitTabs(line, tok);
        if (tok.size() < 2) continue;
        if (tok[0].empty() || tok[0][0] == '#') continue;
        const std::string& c = tok[0];
        CHRPOS sz = strtoll(tok[1].c_str(), nullptr, 10);
        if (_sizes.count(c)) { _sizes[c] = sz; continue; }
        _index[c] = (int)_chroms.size();
        _chroms.push_back(c);
        _starts.push_back(_total);
        _sizes[c] = sz;
        _total += sz;
    }
