// UCSC-style hierarchical binning index for unsorted interval lookups.
#ifndef BT_BININDEX_H
#define BT_BININDEX_H
#include "record.h"
#include <unordered_map>
#include <map>
#include <vector>

class BinIndex {
public:
    BinIndex();
    void add(const RecordPtr& r);
    // Collect candidate records whose *span* overlaps [start,end) on chrom
    // (zero-length records are considered expanded by one base on each side).
    void query(const std::string& chrom, CHRPOS start, CHRPOS end, std::vector<RecordPtr>& hits) const;
    bool hasChrom(const std::string& chrom) const { return _chroms.count(chrom) > 0; }
    size_t size() const { return _count; }
    const std::vector<std::string>& chromOrder() const { return _chromOrder; }
    // all records for a chromosome in insertion order
    const std::vector<RecordPtr>* records(const std::string& chrom) const;
private:
    struct ChromBins {
        std::unordered_map<int, std::vector<RecordPtr>> bins;
        std::vector<RecordPtr> all;
    };
    std::unordered_map<std::string, ChromBins> _chroms;
    std::vector<std::string> _chromOrder;
    size_t _count;
    static int getBin(CHRPOS start, CHRPOS end);
};

// adjusted search coordinates for a record (expands zero-length)
inline void searchCoords(const Record& r, CHRPOS& s, CHRPOS& e) {
    s = r.start; e = r.end;
    if (r.zeroLen) { s = r.start - 1; e = r.end + 1; }
}

