#include "binindex.h"

static const int NUM_BIN_LEVELS = 7;
static const int binOffsets[] = {32768 + 4096 + 512 + 64 + 8 + 1, 4096 + 512 + 64 + 8 + 1, 512 + 64 + 8 + 1, 64 + 8 + 1, 8 + 1, 1, 0};
static const int binFirstShift = 14;
static const int binNextShift = 3;

BinIndex::BinIndex() : _count(0) {}

int BinIndex::getBin(CHRPOS start, CHRPOS end) {
    --end;
    start >>= binFirstShift;
    end >>= binFirstShift;
    for (int i = 0; i < NUM_BIN_LEVELS; i++) {
        if (start == end) return binOffsets[i] + (int)start;
        start >>= binNextShift;
        end >>= binNextShift;
    }
    return -1;
}

void BinIndex::add(const RecordPtr& r) {
    CHRPOS s, e;
    searchCoords(*r, s, e);
    if (s < 0) s = 0;
    if (e <= s) e = s + 1;
    auto it = _chroms.find(r->chrom);
    if (it == _chroms.end()) {
        _chromOrder.push_back(r->chrom);
        it = _chroms.emplace(r->chrom, ChromBins()).first;
    }
    int bin = getBin(s, e);
    if (bin < 0) bin = 0;
    it->second.bins[bin].push_back(r);
    it->second.all.push_back(r);
    _count++;
}

const std::vector<RecordPtr>* BinIndex::records(const std::string& chrom) const {
    auto it = _chroms.find(chrom);
    if (it == _chroms.end()) return nullptr;
    return &it->second.all;
}

void BinIndex::query(const std::string& chrom, CHRPOS start, CHRPOS end, std::vector<RecordPtr>& hits) const {
    auto it = _chroms.find(chrom);
    if (it == _chroms.end()) return;
    const ChromBins& cb = it->second;
    if (start < 0) start = 0;
    if (end <= start) end = start + 1;
    CHRPOS startBin = start >> binFirstShift;
    CHRPOS endBin = (end - 1) >> binFirstShift;
    for (int i = 0; i < NUM_BIN_LEVELS; i++) {
        CHRPOS offset = binOffsets[i];
        for (CHRPOS j = startBin + offset; j <= endBin + offset; j++) {
            auto bit = cb.bins.find((int)j);
            if (bit == cb.bins.end()) continue;
            for (const RecordPtr& r : bit->second) {
                CHRPOS s, e;
                searchCoords(*r, s, e);
                if (s < end && e > start) hits.push_back(r);
            }
        }
        startBin >>= binNextShift;
        endBin >>= binNextShift;
    }
}
