    return args[i + 1];
}

static bool isOptionLike(const std::string& s) { return !s.empty() && s[0] == '-' && s.size() > 1; }

void Context::parseCommon() {
    for (size_t i = 0; i < args.size(); i++) {
        if (used[i]) continue;
        const std::string& a = args[i];
        if (a == "-a" || a == "-i") {
            if (i + 1 >= args.size()) error(a == "-a" ? "-a option given, but no query file specified." : "-i option given, but no input file specified.");
            used[i] = true; used[i + 1] = true;
            aFiles.push_back(args[i + 1]);
            haveA = true;
            i++;
        } else if (a == "-b") {
            if (i + 1 >= args.size() || isOptionLike(args[i + 1])) error("-b option given, but no database file specified.");
            used[i] = true;
            size_t j = i + 1;
            while (j < args.size() && !isOptionLike(args[j])) { bFiles.push_back(args[j]); used[j] = true; j++; }
            haveB = true;
            i = j - 1;
        } else if (a == "-names") {
            used[i] = true;
            size_t j = i + 1;
            while (j < args.size() && !isOptionLike(args[j])) { dbNames.push_back(args[j]); used[j] = true; j++; }
            i = j - 1;
        } else if (a == "-filenames") { used[i] = true; useFilenames = true; }
        else if (a == "-sortout") { used[i] = true; sortOut = true; }
        else if (a == "-g") {
            if (i + 1 >= args.size()) error("-g option given, but no genome file specified.");
            used[i] = true; used[i + 1] = true; genomeFile = args[i + 1]; i++;
        } else if (a == "-f") {
            if (i + 1 >= args.size()) error("Unrecognized parameter: -f");
            used[i] = true; used[i + 1] = true; fracA = atof(args[i + 1].c_str()); haveFracA = true; i++;
        } else if (a == "-F") {
            if (i + 1 >= args.size()) error("Unrecognized parameter: -F");
            used[i] = true; used[i + 1] = true; fracB = atof(args[i + 1].c_str()); haveFracB = true; i++;
        } else if (a == "-r") { used[i] = true; reciprocal = true; }
        else if (a == "-e") { used[i] = true; eitherFrac = true; }
        else if (a == "-s") { used[i] = true; sameStrand = true; }
        else if (a == "-S") { used[i] = true; diffStrand = true; }
        else if (a == "-split") { used[i] = true; split = true; }
        else if (a == "-sorted") { used[i] = true; sorted = true; }
        else if (a == "-nonamecheck") { used[i] = true; noNameCheck = true; }
        else if (a == "-header") { used[i] = true; header = true; }
        else if (a == "-nobuf") { used[i] = true; noBuf = true; g_out.setUnbuffered(true); }
        else if (a == "-bed") { used[i] = true; bedOutput = true; }
        else if (a == "-ubam") { used[i] = true; }
        else if (a == "-iobuf") {
            if (i + 1 >= args.size()) error("Unrecognized parameter: -iobuf");
            used[i] = true; used[i + 1] = true; i++;
        }
    }
}

void Context::finish() {
    for (size_t i = 0; i < args.size(); i++) {
        if (!used[i]) error("Unrecognized parameter: " + args[i]);
    }
}

void Context::validate() {
    if (haveFracA && (fracA <= 0.0 || fracA > 1.0)) error("-f must be in the range (0.0, 1.0].");
    if (haveFracB && (fracB <= 0.0 || fracB > 1.0)) error("-F must be in the range (0.0, 1.0].");
    if (reciprocal && haveFracB) error("-r must be used solely with -f.");
    if (sameStrand && diffStrand) error("request -s for sameStrand, or -S for diffStrand, not both.");
    if (anyHit && noHit) error("request either -u for anyHit OR -v for noHit, not both.");
    if (reciprocal) fracB = fracA;
}

bool Context::strandOK(const Record& a, const Record& b) const {
    if (sameStrand) {
        if (!a.hasStrand() || !b.hasStrand()) return false;
        return a.strand == b.strand;
    }
    if (diffStrand) {
        if (!a.hasStrand() || !b.hasStrand()) return false;
        return a.strand != b.strand;
    }
    return true;
}

CHRPOS Context::computeOverlap(const Record& a, const Record& b) const {
    if (split && (a.type == FT_BED12 || b.type == FT_BED12)) {
        std::vector<Block> ab, bb;
        a.getBlocks(ab, true);
        b.getBlocks(bb, true);
        CHRPOS total = 0;
        for (const Block& x : ab)
            for (const Block& y : bb) {
                CHRPOS o = std::min(x.end, y.end) - std::max(x.start, y.start);
                if (o > 0) total += o;
            }
        return total;
    }
    return std::min(a.end, b.end) - std::max(a.start, b.start);
}

bool Context::overlapOK(const Record& a, const Record& b, CHRPOS& overlap) const {
    if (!strandOK(a, b)) return false;
    overlap = computeOverlap(a, b);
    if (a.zeroLen || b.zeroLen) {
        // zero-length records: any span overlap counts
        if (a.zeroLen && !b.zeroLen) {
            // overlap measured against original coords
            overlap = std::min(a.end, b.end) - std::max(a.start, b.start);
            if (overlap < 0) return false;
        } else if (b.zeroLen && !a.zeroLen) {
            CHRPOS s = b.start - 1, e = b.end + 1;
            overlap = std::min(a.end, e) - std::max(a.start, s) - 2;
            if (overlap < -1) return false;
        } else {
            overlap = 0;
        }
        return true;
    }
    if (overlap <= 0) return false;
    CHRPOS aLen, bLen;
    if (split && (a.type == FT_BED12 || b.type == FT_BED12)) {
        std::vector<Block> blocks;
        a.getBlocks(blocks, true); aLen = 0; for (auto& x : blocks) aLen += x.end - x.start;
        b.getBlocks(blocks, true); bLen = 0; for (auto& x : blocks) bLen += x.end - x.start;
    } else { aLen = a.length(); bLen = b.length(); }
    if (aLen <= 0) aLen = 1;
    if (bLen <= 0) bLen = 1;
    bool okA = ((double)overlap / (double)aLen) >= fracA;
    bool okB = ((double)overlap / (double)bLen) >= fracB;
    if (eitherFrac) return okA || okB;
    return okA && okB;
}

void printHeaderIfRequested(const Context& ctx, const RecordFile& rf) {
    if (!ctx.header) return;
    for (const std::string& h : rf.header()) {
        g_out.write(h);
        g_out.write('\n');
    }
}
