            CHRPOS s = b.start - 1, e = b.end + 1;
            overlap = std::min(a.end, e) - std::max(a.start, s) - 2;
            if (overlap < -1) return false;
        } else {
            overlap = 0;
        }
        return true;
    }
    if (overlap <= 0) return false;
    CHRPOS aLen, bLen;
    if (split && (a.type == FT_BED12 || b.type == FT_BED12)) {
        std::vector<Block> blocks;
        a.getBlocks(blocks, true); aLen = 0; for (auto& x : blocks) aLen += x.end - x.start;
        b.getBlocks(blocks, true); bLen = 0; for (auto& x : blocks) bLen += x.end - x.start;
    } else { aLen = a.length(); bLen = b.length(); }
    if (aLen <= 0) aLen = 1;
    if (bLen <= 0) bLen = 1;
    bool okA = ((double)overlap / (double)aLen) >= fracA;
    bool okB = ((double)overlap / (double)bLen) >= fracB;
    if (eitherFrac) return okA || okB;
    return okA && okB;
}

void printHeaderIfRequested(const Context& ctx, const RecordFile& rf) {
    if (!ctx.header) return;
    for (const std::string& h : rf.header()) {
        g_out.write(h);
        g_out.write('\n');
    }
}
