#include "hitfinder.h"
#include <algorithm>

HitFinder::HitFinder(Context& ctx) : _ctx(ctx) {
    if (!ctx.genomeFile.empty()) {
        LineReader lr;
        if (!lr.open(ctx.genomeFile)) {
            fatal("Error: Can't open genome file " + ctx.genomeFile + ". Exiting...\n");
        }
        lr.close();
        _genome.load(ctx.genomeFile);
        _haveGenome = true;
    }
}

void HitFinder::checkSortedRecord(const Record& r, const std::string& fname, std::string& lastChrom, CHRPOS& lastStart,
                                  std::vector<std::string>& order) {
    if (_haveGenome) {
        if (!_genome.hasChrom(r.chrom)) {
            fatal("Error: requested chromosome " + r.chrom + " does not exist in the genome file " + _ctx.genomeFile + ". Exiting.\n");
        }
    }
    if (!_ctx.sorted) return;
    if (r.chrom == lastChrom) {
        if (r.start < lastStart) {
            std::string s; r.print(s);
            fatal("Error: Sorted input specified, but the file " + fname + " has the following out of order record\n" + s + "\n");
        }
        lastStart = r.start;
        return;
    }
    // new chromosome
    if (std::find(order.begin(), order.end(), r.chrom) != order.end()) {
        std::string s; r.print(s);
        fatal("Error: Sorted input specified, but the file " + fname + " has the following out of order record\n" + s + "\n");
    }
    if (_haveGenome) {
        // chrom order must follow genome
        if (!lastChrom.empty() && _genome.index(r.chrom) < _genome.index(lastChrom)) {
            std::string s; r.print(s);
            fatal("Error: Sorted input specified, but the file " + fname + " has the following record with a different sort order than the genomeFile " + _ctx.genomeFile + "\n" + s + "\n");
        }
    } else if (!_ctx.noNameCheck) {
        // consistency with global order: if both chroms seen globally, order must match
        auto itNew = std::find(_globalChromOrder.begin(), _globalChromOrder.end(), r.chrom);
        auto itOld = std::find(_globalChromOrder.begin(), _globalChromOrder.end(), lastChrom);
        if (itNew != _globalChromOrder.end() && itOld != _globalChromOrder.end() && itNew < itOld) {
            std::string s; r.print(s);
            fatal("ERROR: chromosome sort ordering for file " + fname + " is inconsistent with other files. Record was:\n" + s + "\n");
        }
        if (itNew == _globalChromOrder.end()) _globalChromOrder.push_back(r.chrom);
    }
    order.push_back(r.chrom);
    lastChrom = r.chrom;
    lastStart = r.start;
}

void HitFinder::loadDatabases() {
    for (size_t i = 0; i < _ctx.bFiles.size(); i++) {
        RecordFile rf;
        rf.open(_ctx.bFiles[i], (int)i);
        BinIndex* idx = new BinIndex();
        std::string lastChrom; CHRPOS lastStart = -1; std::vector<std::string> order;
        RecordPtr r;
        long seq = 0;
        while ((r = rf.next())) {
            r->lineNum = seq++;
            checkSortedRecord(*r, _ctx.bFiles[i], lastChrom, lastStart, order);
            idx->add(r);
        }
        _dbs.push_back(idx);
        _dbTypes.push_back(rf.type());
        _dbNumFields.push_back(rf.numFields());
        _dbChromOrder.push_back(order);
    }
}

void HitFinder::checkSortedA(const Record& a, const std::string& fname) {
    checkSortedRecord(a, fname, _lastChromA, _lastStartA, _chromOrderA);
}

void HitFinder::query(int db, const std::string& chrom, CHRPOS s, CHRPOS e, std::vector<RecordPtr>& out) const {
    std::vector<RecordPtr> tmp;
    _dbs[db]->query(chrom, s, e, tmp);
    if (_ctx.sorted) {
        std::stable_sort(tmp.begin(), tmp.end(), [](const RecordPtr& x, const RecordPtr& y) { return x->lineNum < y->lineNum; });
    }
    out.insert(out.end(), tmp.begin(), tmp.end());
}

void HitFinder::find(const Record& a, std::vector<Hit>& hits) {
    hits.clear();
    CHRPOS s, e;
    searchCoords(a, s, e);
    std::vector<RecordPtr> cands;
    for (int d = 0; d < (int)_dbs.size(); d++) {
        cands.clear();
        query(d, a.chrom, s, e, cands);
        for (const RecordPtr& b : cands) {
            CHRPOS ov;
            if (_ctx.overlapOK(a, *b, ov)) hits.push_back({b, ov});
        }
    }
    if (_ctx.sortOut) {
        std::stable_sort(hits.begin(), hits.end(), [](const Hit& x, const Hit& y) {
            if (x.rec->start != y.rec->start) return x.rec->start < y.rec->start;
            return x.rec->end < y.rec->end;
        });
    }
}

std::string HitFinder::dbLabel(int db) const {
    if (!_ctx.dbNames.empty() && db < (int)_ctx.dbNames.size()) return _ctx.dbNames[db];
    if (_ctx.useFilenames) return _ctx.bFiles[db];
    return toStr(db + 1);
}
