#include "vectorops.h"
#include <algorithm>
#include <cmath>
#include <map>
#include <set>
#include <sstream>
#include <iomanip>
#include <cerrno>

VectorOps::VectorOps(const std::string& delim, int precision) : _delim(delim), _prec(precision) {}

static const char* VALID_OPS[] = {
    "sum", "min", "max", "absmin", "absmax", "mean", "median", "mode", "antimode", "stdev", "sstdev",
    "collapse", "distinct", "distinct_sort_num", "distinct_sort_num_desc", "distinct_only", "count",
    "count_distinct", "first", "last", "concat", "freqdesc", "freqasc", nullptr
};

bool VectorOps::isValidOp(const std::string& op, bool) {
    for (int i = 0; VALID_OPS[i]; i++) if (op == VALID_OPS[i]) return true;
    return false;
}

bool VectorOps::isNumericOp(const std::string& op) {
    return op == "sum" || op == "min" || op == "max" || op == "absmin" || op == "absmax" || op == "mean" ||
           op == "median" || op == "stdev" || op == "sstdev" || op == "distinct_sort_num" || op == "distinct_sort_num_desc";
}

std::string VectorOps::fmt(double v) const {
    std::ostringstream os;
    os << std::setprecision(_prec) << v;
    return os.str();
}
std::string VectorOps::fmtInt(long long v) const { return toStr((CHRPOS)v); }

double VectorOps::toNum(const std::string& s, const std::string& op, bool& ok) const {
    char* end = nullptr;
    errno = 0;
    double v = strtod(s.c_str(), &end);
    if (end == s.c_str() || *end != '\0') { ok = false; return 0.0; }
    ok = true;
    return v;
}

void VectorOps::buildOps(const std::string& cols, const std::string& ops, std::vector<ColumnOp>& out, std::string& err) {
    std::vector<std::string> c, o;
    splitOn(cols, ',', c);
    splitOn(ops, ',', o);
    out.clear();
    if (c.size() == o.size()) {
        for (size_t i = 0; i < c.size(); i++) out.push_back({atoi(c[i].c_str()), o[i]});
    } else if (c.size() == 1) {
        for (size_t i = 0; i < o.size(); i++) out.push_back({atoi(c[0].c_str()), o[i]});
    } else if (o.size() == 1) {
        for (size_t i = 0; i < c.size(); i++) out.push_back({atoi(c[i].c_str()), o[0]});
    } else {
        err = "There are " + std::to_string(c.size()) + " columns given, but there are " + std::to_string(o.size()) +
              " operations.\n\tPlease provide either a single column, a single operation, or an equal number of columns and operations.";
        return;
    }
    for (const ColumnOp& co : out) {
        if (!isValidOp(co.op)) { err = co.op + " is not a valid operation."; return; }
    }
}

std::string VectorOps::apply(const std::string& op, std::vector<std::string>& vals, const std::string& nullValue) const {
    if (op == "count") return fmtInt((long long)vals.size());
    if (vals.empty()) return nullValue;
    if (op == "collapse") {
        std::string s;
        for (size_t i = 0; i < vals.size(); i++) { if (i) s += _delim; s += vals[i]; }
        return s;
    }
    if (op == "concat") {
        std::string s;
        for (size_t i = 0; i < vals.size(); i++) s += vals[i];
        return s;
    }
    if (op == "first") return vals.front();
    if (op == "last") return vals.back();
    if (op == "distinct" || op == "distinct_only" || op == "count_distinct") {
        std::vector<std::string> uniq;
        std::set<std::string> seen;
        std::map<std::string, int> counts;
        for (const std::string& v : vals) {
            counts[v]++;
            if (seen.insert(v).second) uniq.push_back(v);
        }
        if (op == "count_distinct") return fmtInt((long long)uniq.size());
        std::string s; bool first = true;
        for (const std::string& v : uniq) {
            if (op == "distinct_only" && counts[v] > 1) continue;
            if (!first) s += _delim;
            s += v; first = false;
        }
        return s;
    }
    if (op == "distinct_sort_num" || op == "distinct_sort_num_desc") {
        std::vector<double> nums;
        for (const std::string& v : vals) { bool ok; double d = toNum(v, op, ok); if (!ok) { fatal("***** ERROR: Non numeric value " + v + " in column. *****\n"); } nums.push_back(d); }
        std::sort(nums.begin(), nums.end());
        nums.erase(std::unique(nums.begin(), nums.end()), nums.end());
        if (op == "distinct_sort_num_desc") std::reverse(nums.begin(), nums.end());
        std::string s;
        for (size_t i = 0; i < nums.size(); i++) { if (i) s += _delim; s += fmt(nums[i]); }
        return s;
    }
    if (op == "mode" || op == "antimode" || op == "freqdesc" || op == "freqasc") {
        std::map<std::string, int> counts;
        for (const std::string& v : vals) counts[v]++;
        if (op == "mode" || op == "antimode") {
            std::string best; int bestCount = (op == "mode") ? -1 : 0x7fffffff;
            for (auto& kv : counts) {
                if (op == "mode" ? kv.second > bestCount : kv.second < bestCount) { best = kv.first; bestCount = kv.second; }
            }
            return best;
        }
        std::vector<std::pair<std::string, int>> items(counts.begin(), counts.end());
        if (op == "freqdesc")
            std::stable_sort(items.begin(), items.end(), [](const std::pair<std::string,int>& a, const std::pair<std::string,int>& b) { return a.second > b.second; });
        else
            std::stable_sort(items.begin(), items.end(), [](const std::pair<std::string,int>& a, const std::pair<std::string,int>& b) { return a.second < b.second; });
        std::string s;
        for (size_t i = 0; i < items.size(); i++) { if (i) s += _delim; s += items[i].first + ":" + toStr((CHRPOS)items[i].second); }
        return s;
    }
    // numeric ops
    std::vector<double> nums;
    nums.reserve(vals.size());
    for (const std::string& v : vals) {
        bool ok; double d = toNum(v, op, ok);
