#include "context.h"
#include "tools.h"
#include "vectorops.h"
#include <deque>
#include <algorithm>
#include <map>

// Merge manager mimicking the stored-record approach: records of the wrong strand
// encountered while building a block are kept in storage (FIFO) and considered first
// when starting/extending subsequent blocks.
struct MergeBlock {
    CHRPOS start, end;
    std::string chrom;
    std::vector<RecordPtr> recs;
};

class Merger {
public:
    Merger(RecordFile& rf, CHRPOS maxDist, int strandMode, char onlyStrand)
        : _rf(rf), _maxDist(maxDist), _strandMode(strandMode), _onlyStrand(onlyStrand), _eof(false) {}
    // strandMode: 0 any, 1 same strand (either), 2 specific strand (_onlyStrand)
    bool next(MergeBlock& blk);
    void checkSorted(const Record& r);
private:
    RecordFile& _rf;
    CHRPOS _maxDist;
    int _strandMode;
    char _onlyStrand;
    bool _eof;
    std::deque<RecordPtr> _storage;
    std::string _lastChrom; CHRPOS _lastStart = -1; std::vector<std::string> _seenChroms;
    RecordPtr readFile();
};

void Merger::checkSorted(const Record& r) {
    if (r.chrom == _lastChrom) {
        if (r.start < _lastStart) {
            std::string s; r.print(s);
            fatal("Error: Sorted input specified, but the file " + _rf.name() + " has the following out of order record\n" + s + "\n");
        }
        _lastStart = r.start;
        return;
    }
    if (std::find(_seenChroms.begin(), _seenChroms.end(), r.chrom) != _seenChroms.end()) {
        std::string s; r.print(s);
        fatal("Error: Sorted input specified, but the file " + _rf.name() + " has the following out of order record\n" + s + "\n");
    }
    _seenChroms.push_back(r.chrom);
    _lastChrom = r.chrom;
    _lastStart = r.start;
}

RecordPtr Merger::readFile() {
    while (!_eof) {
        RecordPtr r = _rf.next();
        if (!r) { _eof = true; return nullptr; }
        checkSorted(*r);
        if (_strandMode == 2 && r->strand != _onlyStrand) continue;
        return r;
    }
    return nullptr;
}

bool Merger::next(MergeBlock& blk) {
    RecordPtr start;
    if (!_storage.empty()) { start = _storage.front(); _storage.pop_front(); }
    else start = readFile();
    if (!start) return false;
    blk.chrom = start->chrom;
    blk.start = start->start;
    blk.end = start->end;
    blk.recs.clear();
    blk.recs.push_back(start);
    char curStrand = start->strand;
    bool mustMatch = (_strandMode == 1);
    size_t storeIdx = 0;  // next storage position to examine
    while (true) {
        RecordPtr nxt;
        bool fromStorage = false;
        // look in storage (first matching record)
        while (storeIdx < _storage.size()) {
            const RecordPtr& c = _storage[storeIdx];
            if (!mustMatch || c->strand == curStrand) { nxt = c; fromStorage = true; break; }
            storeIdx++;
        }
        if (!nxt) nxt = readFile();
        if (!nxt) break;
        if (nxt->chrom != blk.chrom) {
            if (!fromStorage) _storage.push_back(nxt);
            break;
        }
        if (nxt->start - blk.end > _maxDist) {
            if (!fromStorage) _storage.push_back(nxt);
            break;
        }
        if (mustMatch && nxt->strand != curStrand) {
            if (!fromStorage) _storage.push_back(nxt);
            continue;
        }
        if (fromStorage) _storage.erase(_storage.begin() + storeIdx);
        if (nxt->end > blk.end) blk.end = nxt->end;
        blk.recs.push_back(nxt);
    }
    return true;
}

int merge_main(int argc, char** argv) {
    Context ctx("merge", argc, argv);
    CHRPOS maxDist = 0;
    int strandMode = 0; char onlyStrand = 0;
    std::string cols, ops, delim = ",";
    int prec = 5;
    bool haveCols = false, haveOps = false;
    for (size_t i = 0; i < ctx.args.size(); i++) {
        if (ctx.isUsed(i)) continue;
        const std::string& a = ctx.args[i];
        if (a == "-s") { strandMode = 1; ctx.markUsed(i); }
        else if (a == "-S") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size() || (ctx.args[i + 1] != "+" && ctx.args[i + 1] != "-"))
                ctx.error("-S option requires either + or - as an argument.");
            strandMode = 2; onlyStrand = ctx.args[i + 1][0]; ctx.markUsed(i + 1); i++;
        } else if (a == "-d") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-d option given, but no distance specified.");
            maxDist = strtoll(ctx.args[i + 1].c_str(), nullptr, 10); ctx.markUsed(i + 1); i++;
        } else if (a == "-c") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-c option given, but no columns specified.");
            cols = ctx.args[i + 1]; haveCols = true; ctx.markUsed(i + 1); i++;
        } else if (a == "-o") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-o option given, but no operations specified.");
            ops = ctx.args[i + 1]; haveOps = true; ctx.markUsed(i + 1); i++;
        } else if (a == "-delim") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-delim option given, but no delimiter specified.");
            delim = ctx.args[i + 1]; ctx.markUsed(i + 1); i++;
        } else if (a == "-prec") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-prec option given, but no precision specified.");
            prec = atoi(ctx.args[i + 1].c_str()); ctx.markUsed(i + 1); i++;
        }
    }
    // "-s" is handled here (strand mode), so remove from common parse by marking used already
    ctx.parseCommon();
    ctx.finish();
    ctx.validate();
    std::string inFile = ctx.haveA ? ctx.aFiles[0] : "stdin";
    if (ctx.args.empty()) inFile = "stdin";

    std::vector<ColumnOp> colOps;
    if (haveCols || haveOps) {
        if (!haveCols) cols = "5";
        if (!haveOps) ops = "sum";
        std::string err;
        VectorOps::buildOps(cols, ops, colOps, err);
        if (!err.empty()) ctx.error(err);
    }
    VectorOps vops(delim, prec);

    RecordFile rf;
    rf.open(inFile, 0);
    printHeaderIfRequested(ctx, rf);
    Merger merger(rf, maxDist, strandMode, onlyStrand);
    MergeBlock blk;
    std::string out;
    std::vector<std::string> vals;
    while (merger.next(blk)) {
        out.clear();
        out += blk.chrom; out += '\t'; out += toStr(blk.start); out += '\t'; out += toStr(blk.end);
        for (const ColumnOp& co : colOps) {
            vals.clear();
            for (const RecordPtr& r : blk.recs) {
                if (co.column < 1 || co.column > (int)r->f.size()) {
                    fatal("***** ERROR: requested column " + toStr(co.column) + " exceeds the number of columns in file at line " + toStr((CHRPOS)r->lineNum) + ". Exiting. *****\n");
                }
                vals.push_back(r->f[co.column - 1]);
            }
            out += '\t';
            out += vops.apply(co.op, vals, ".");
        }
        out += '\n';
        g_out.write(out);
    }
    return 0;
}
