int cluster_main(int argc, char** argv) {
    std::string inFile = "stdin";
    bool stranded = false;
    CHRPOS maxDist = 0;
    bool showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-i") { if (i + 1 < argc) { inFile = argv[++i]; } else showHelp = true; }
        else if (a == "-s") stranded = true;
        else if (a == "-d") { if (i + 1 < argc) { maxDist = strtoll(argv[++i], nullptr, 10); } else showHelp = true; }
        else {
            fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]);
            showHelp = true;
        }
    }
    if (showHelp) { printHelp("cluster"); return 1; }

    std::vector<RecordPtr> recs;
    readAllRecords(inFile, recs);
    // group by chromosome (lexicographic), preserve input order within chrom, then sort by start
    std::map<std::string, std::vector<RecordPtr>> byChrom;
    for (const RecordPtr& r : recs) byChrom[r->chrom].push_back(r);
    long clusterId = 0;
    std::string out;
    auto clusterList = [&](std::vector<RecordPtr>& list) {
        std::stable_sort(list.begin(), list.end(), [](const RecordPtr& a, const RecordPtr& b) {
            return a->start < b->start;
        });
        CHRPOS curEnd = -1;
        bool first = true;
        for (const RecordPtr& r : list) {
            if (first || r->start - curEnd > maxDist) {
                clusterId++;
                curEnd = r->end;
                first = false;
            } else if (r->end > curEnd) {
                curEnd = r->end;
            }
            out.clear();
            r->print(out);
            out += '\t'; out += toStr((CHRPOS)clusterId); out += '\n';
            g_out.write(out);
        }
    };
    for (auto& kv : byChrom) {
        if (!stranded) {
            clusterList(kv.second);
        } else {
            std::vector<RecordPtr> plus, minus;
            for (const RecordPtr& r : kv.second) {
                if (r->strand == '+') plus.push_back(r);
                else if (r->strand == '-') minus.push_back(r);
            }
            clusterList(plus);
            clusterList(minus);
        }
    }
    return 0;
}
