#include "classic.h"
#include "tools.h"
#include <map>
#include <algorithm>

static bool byStart(const RecordPtr& a, const RecordPtr& b) { return a->start < b->start; }
static bool bySizeAsc(const RecordPtr& a, const RecordPtr& b) { return a->length() < b->length(); }
static bool bySizeDesc(const RecordPtr& a, const RecordPtr& b) { return a->length() > b->length(); }
static bool byScoreAsc(const RecordPtr& a, const RecordPtr& b) { return a->score() < b->score(); }
static bool byScoreDesc(const RecordPtr& a, const RecordPtr& b) { return a->score() > b->score(); }

int sort_main(int argc, char** argv) {
    std::string inFile = "stdin";
    std::string genomeFile, faidxFile;
    bool header = false;
    int mode = 0; // 0 default, 1 sizeA, 2 sizeD, 3 chrThenSizeA, 4 chrThenSizeD, 5 chrThenScoreA, 6 chrThenScoreD
    bool showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-i") { if (i + 1 < argc) inFile = argv[++i]; else showHelp = true; }
        else if (a == "-sizeA") mode = 1;
        else if (a == "-sizeD") mode = 2;
        else if (a == "-chrThenSizeA") mode = 3;
        else if (a == "-chrThenSizeD") mode = 4;
        else if (a == "-chrThenScoreA") mode = 5;
        else if (a == "-chrThenScoreD") mode = 6;
        else if (a == "-g") { if (i + 1 < argc) genomeFile = argv[++i]; else showHelp = true; }
        else if (a == "-faidx") { if (i + 1 < argc) faidxFile = argv[++i]; else showHelp = true; }
        else if (a == "-header") header = true;
        else {
            fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]);
            showHelp = true;
        }
    }
    if (showHelp) { printHelp("sort"); return 1; }

    std::vector<RecordPtr> recs;
    std::vector<std::string> hdr;
    readAllRecords(inFile, recs, 0, &hdr);
    std::string out;
    if (header) for (const std::string& h : hdr) { out += h; out += '\n'; }

    auto emit = [&](const std::vector<RecordPtr>& v) {
        for (const RecordPtr& r : v) { r->print(out); out += '\n'; if (out.size() > 65536) { g_out.write(out); out.clear(); } }
    };

    if (mode == 1 || mode == 2) {
        std::sort(recs.begin(), recs.end(), mode == 1 ? bySizeAsc : bySizeDesc);
        emit(recs);
        g_out.write(out);
        return 0;
    }
    // group by chromosome
    std::map<std::string, std::vector<RecordPtr>> byChrom;
    std::vector<std::string> chromOrder;
    for (const RecordPtr& r : recs) {
        auto it = byChrom.find(r->chrom);
        if (it == byChrom.end()) { chromOrder.push_back(r->chrom); byChrom[r->chrom].push_back(r); }
        else it->second.push_back(r);
    }
    bool (*cmp)(const RecordPtr&, const RecordPtr&) = byStart;
    if (mode == 3) cmp = bySizeAsc; else if (mode == 4) cmp = bySizeDesc;
    else if (mode == 5) cmp = byScoreAsc; else if (mode == 6) cmp = byScoreDesc;
    for (auto& kv : byChrom) std::sort(kv.second.begin(), kv.second.end(), cmp);

    if (!genomeFile.empty() || !faidxFile.empty()) {
        GenomeFile g;
        g.load(genomeFile.empty() ? faidxFile : genomeFile);
        for (const std::string& c : g.chroms()) {
            auto it = byChrom.find(c);
            if (it != byChrom.end()) emit(it->second);
        }
        // chromosomes not in genome: error
        for (auto& kv : byChrom) {
            if (!g.hasChrom(kv.first)) {
                g_out.write(out); out.clear();
                fatal("***** ERROR: chromosome " + kv.first + " is not in the genome file *****\n");
            }
        }
    } else {
        for (auto& kv : byChrom) emit(kv.second);  // lexicographic chrom order
    }
    g_out.write(out);
    return 0;
}
