#include "context.h"
#include "hitfinder.h"
#include "tools.h"
#include <algorithm>
#include <map>

namespace {

struct Cand {
    RecordPtr rec;
    CHRPOS absDist;
    CHRPOS signedDist;
    bool upstream;
};

// distance between a and b (1 for bookended, 0 for overlap)
static CHRPOS rawDistance(const Record& a, const Record& b, bool& bAfter) {
    CHRPOS as = a.start, ae = a.end, bs = b.start, be = b.end;
    if (a.zeroLen) { as = a.start - 1; ae = a.end + 1; }
    if (b.zeroLen) { bs = b.start - 1; be = b.end + 1; }
    if (bs < ae && be > as) { bAfter = false; return 0; }
    if (bs >= ae) { bAfter = true; return bs - ae + 1; }
    bAfter = false;
    return as - be + 1;
}

} // namespace

int closest_main(int argc, char** argv) {
    Context ctx("closest", argc, argv);
    bool reportDist = false, signedDist = false;
    std::string distMode = "ref";
    bool ignoreOverlaps = false, ignoreUpstream = false, ignoreDownstream = false, firstUp = false, firstDown = false;
    std::string tieMode = "all", mdb = "each";
    int k = 1;
    bool diffNames = false;
    for (size_t i = 0; i < ctx.args.size(); i++) {
        const std::string& a = ctx.args[i];
        if (a == "-d") { reportDist = true; ctx.markUsed(i); }
        else if (a == "-D") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-D option given, but no distance mode specified.");
            distMode = ctx.args[i + 1]; ctx.markUsed(i + 1); i++;
            signedDist = true; reportDist = true;
            if (distMode != "ref" && distMode != "a" && distMode != "b") ctx.error("Invalid -D option specified. Must be ref, a, or b.");
        } else if (a == "-io") { ignoreOverlaps = true; ctx.markUsed(i); }
        else if (a == "-iu") { ignoreUpstream = true; ctx.markUsed(i); }
        else if (a == "-id") { ignoreDownstream = true; ctx.markUsed(i); }
        else if (a == "-fu") { firstUp = true; ctx.markUsed(i); }
        else if (a == "-fd") { firstDown = true; ctx.markUsed(i); }
        else if (a == "-t") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-t option given, but no tie mode specified.");
            tieMode = ctx.args[i + 1]; ctx.markUsed(i + 1); i++;
            if (tieMode != "all" && tieMode != "first" && tieMode != "last") ctx.error("Invalid -t option specified. Must be all, first, or last.");
        } else if (a == "-mdb") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-mdb option given, but no mode specified.");
            mdb = ctx.args[i + 1]; ctx.markUsed(i + 1); i++;
            if (mdb != "each" && mdb != "all") ctx.error("Invalid -mdb option specified. Must be each or all.");
        } else if (a == "-k") {
            ctx.markUsed(i);
            if (i + 1 >= ctx.args.size()) ctx.error("-k option given, but no number specified.");
            k = atoi(ctx.args[i + 1].c_str()); ctx.markUsed(i + 1); i++;
            if (k < 1) ctx.error("-k must be greater than or equal to 1.");
        } else if (a == "-N") { diffNames = true; ctx.markUsed(i); }
    }
    ctx.parseCommon();
    ctx.finish();
    if (!ctx.haveA || !ctx.haveB) {
        if (ctx.haveA) ctx.error("query and database files not specified.");
        ctx.error("No input file given. Exiting.");
    }
    if (!ctx.dbNames.empty() && ctx.dbNames.size() != ctx.bFiles.size())
        ctx.error("Number of database name tags given does not match number of databases.");
    if ((ignoreUpstream || ignoreDownstream || firstUp || firstDown) && !signedDist)
        ctx.error("When using -iu, -id, -fu, or -fd, the -D option must also be used.");
    if (ignoreUpstream && ignoreDownstream) ctx.error("Cannot use both -iu and -id.");
    ctx.validate();
    ctx.sorted = true;  // closest requires sorted input

    RecordFile af;
    af.open(ctx.aFiles[0], 0);
    HitFinder hf(ctx);
    hf.loadDatabases();
    printHeaderIfRequested(ctx, af);
    bool showDb = hf.numDbs() > 1 || !ctx.dbNames.empty() || ctx.useFilenames;

    std::string out;
    RecordPtr a;
    std::vector<Cand> cands, chosen;
    while ((a = af.next())) {
        hf.checkSortedA(*a, ctx.aFiles[0]);
        out.clear();
        int groups = (mdb == "all") ? 1 : hf.numDbs();
        for (int gi = 0; gi < groups; gi++) {
            cands.clear();
