#include "tools.h"
#include <algorithm>

int subtract_main(int argc, char** argv) {
    Context ctx("subtract", argc, argv);
    bool removeAll = false, removeSum = false, writeB = false, writeOverlap = false;
    for (size_t i = 0; i < ctx.args.size(); i++) {
        const std::string& a = ctx.args[i];
        if (a == "-A") { removeAll = true; ctx.markUsed(i); }
        else if (a == "-N") { removeSum = true; ctx.markUsed(i); }
        else if (a == "-wb") { writeB = true; ctx.markUsed(i); }
        else if (a == "-wo") { writeOverlap = true; ctx.markUsed(i); }
    }
    ctx.parseCommon();
    ctx.finish();
    if (!ctx.haveA || !ctx.haveB) {
        if (ctx.haveA) ctx.error("query and database files not specified.");
        ctx.error("No input file given. Exiting.");
    }
    ctx.validate();

    RecordFile af;
    af.open(ctx.aFiles[0], 0);
    HitFinder hf(ctx);
    hf.loadDatabases();
    printHeaderIfRequested(ctx, af);

    std::vector<Hit> hits;
    std::string out;
    RecordPtr a;
    while ((a = af.next())) {
        hf.checkSortedA(*a, ctx.aFiles[0]);
        hf.find(*a, hits);
        out.clear();
        if (hits.empty()) {
            a->print(out); out.push_back('\n');
            g_out.write(out);
            continue;
        }
        if (removeAll && !removeSum) continue;  // any qualifying hit removes the feature
        // merge hit intervals clipped to A
        std::vector<std::pair<CHRPOS, CHRPOS>> ivls;
        CHRPOS covered = 0;
        for (const Hit& h : hits) {
            std::vector<Block> blocks;
            h.rec->getBlocks(blocks, ctx.split);
            for (const Block& b : blocks) {
                CHRPOS s = std::max(b.start, a->start), e = std::min(b.end, a->end);
                if (e > s) ivls.push_back({s, e});
            }
        }
        std::sort(ivls.begin(), ivls.end());
        std::vector<std::pair<CHRPOS, CHRPOS>> merged;
        for (const auto& iv : ivls) {
            if (!merged.empty() && iv.first <= merged.back().second) merged.back().second = std::max(merged.back().second, iv.second);
            else merged.push_back(iv);
        }
        for (const auto& iv : merged) covered += iv.second - iv.first;
        if (removeSum) {
            double frac = a->length() > 0 ? (double)covered / (double)a->length() : 1.0;
            if (frac >= ctx.fracA) continue;
            a->print(out); out.push_back('\n');
            g_out.write(out);
            continue;
        }
        if (writeB || writeOverlap) {
            for (const Hit& h : hits) {
                a->print(out); out.push_back('\t'); h.rec->print(out);
                if (writeOverlap) { out.push_back('\t'); out.append(toStr(h.overlap)); }
                out.push_back('\n');
            }
            g_out.write(out);
            continue;
        }
        CHRPOS pos = a->start;
        for (const auto& iv : merged) {
            if (iv.first > pos) { a->printWithCoords(out, pos, iv.first); out.push_back('\n'); }
            pos = std::max(pos, iv.second);
        }
        if (pos < a->end) { a->printWithCoords(out, pos, a->end); out.push_back('\n'); }
        if (!out.empty()) g_out.write(out);
    }
    return 0;
}
