#include "classic.h"
#include "tools.h"
#include <cmath>

// Shared parsing for slop/flank: -i -g -b -l -r -s -pct -header
struct SlopArgs {
    std::string inFile, genomeFile;
    double b = 0, l = 0, r = 0;
    bool haveB = false, haveL = false, haveR = false;
    bool stranded = false, pct = false, header = false;
};

static bool parseSlopArgs(const char* tool, int argc, char** argv, SlopArgs& s) {
    bool showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-i") { if (i + 1 < argc) s.inFile = argv[++i]; else showHelp = true; }
        else if (a == "-g") { if (i + 1 < argc) s.genomeFile = argv[++i]; else showHelp = true; }
        else if (a == "-b") { if (i + 1 < argc) { s.b = atof(argv[++i]); s.haveB = true; } else showHelp = true; }
        else if (a == "-l") { if (i + 1 < argc) { s.l = atof(argv[++i]); s.haveL = true; } else showHelp = true; }
        else if (a == "-r") { if (i + 1 < argc) { s.r = atof(argv[++i]); s.haveR = true; } else showHelp = true; }
        else if (a == "-s") s.stranded = true;
        else if (a == "-pct") s.pct = true;
        else if (a == "-header") s.header = true;
        else {
            fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]);
            showHelp = true;
        }
    }
    if (showHelp) { printHelp(tool); exit(1); }
    bool fail = false;
    if (s.inFile.empty() || s.genomeFile.empty()) { classicErrorMsg("Need both a BED (-i) and a genome (-g) file."); fail = true; }
    if (!s.haveB && !(s.haveL && s.haveR)) { classicErrorMsg("Need -l and -r together or -b alone."); fail = true; }
    if (s.haveB && (s.haveL || s.haveR)) { classicErrorMsg("Can't combine -b with -l and -r."); fail = true; }
    if (s.haveB) { s.l = s.b; s.r = s.b; }
    if (fail) { printHelp(tool); exit(1); }
    return true;
}

static CHRPOS chromSizeOrDie(const GenomeFile& g, const Record& r) {
    CHRPOS sz = g.size(r.chrom);
    if (sz < 0) {
        fatal("***** ERROR: chromosome " + r.chrom + " is not found in the genome file. Exiting. *****\n");
    }
    return sz;
}

int slop_main(int argc, char** argv) {
    SlopArgs s;
    parseSlopArgs("slop", argc, argv, s);
    GenomeFile g; g.load(s.genomeFile);
    RecordFile rf; rf.open(s.inFile);
    if (s.header) for (const std::string& h : rf.header()) { g_out.write(h); g_out.write('\n'); }
    RecordPtr r; std::string out;
    while ((r = rf.next())) {
        CHRPOS chromSize = chromSizeOrDie(g, *r);
        CHRPOS left, right;
        if (s.pct) { left = (CHRPOS)(s.l * (double)r->length()); right = (CHRPOS)(s.r * (double)r->length()); }
        else { left = (CHRPOS)s.l; right = (CHRPOS)s.r; }
        if (s.stranded && r->strand == '-') std::swap(left, right);
        CHRPOS ns = r->start, ne = r->end;
        if (ns - left > 0) ns -= left; else ns = 0;
        if (ne + right <= chromSize) ne += right; else ne = chromSize;
        if (ns > ne) ne = ns;  // keep interval valid
        out.clear();
        r->printWithCoords(out, ns, ne); out.push_back('\n');
        g_out.write(out);
    }
    return 0;
}

int flank_main(int argc, char** argv) {
    SlopArgs s;
    parseSlopArgs("flank", argc, argv, s);
    GenomeFile g; g.load(s.genomeFile);
    RecordFile rf; rf.open(s.inFile);
    if (s.header) for (const std::string& h : rf.header()) { g_out.write(h); g_out.write('\n'); }
