#include "classic.h"
#include "tools.h"
#include <map>
#include <set>
#include <algorithm>

namespace {

struct GCovArgs {
    std::string inFile, genomeFile;
    bool eachBase = false, eachBaseZero = false, bedGraph = false, bedGraphAll = false;
    bool split = false, ignoreD = false, pc = false, du = false, only5 = false, only3 = false;
    bool trackline = false;
    std::string trackopts;
    std::string strand;
    int fs = 0;
    long maxDepth = -1;
    double scale = 1.0;
    bool bam = false;
};

static std::string fmtFloat(double v) {
    // mimic `cout << (float)v` (default 6 significant digits)
    char buf[64];
    snprintf(buf, sizeof(buf), "%g", (double)(float)v);
    return std::string(buf);
}

class GenomeCov {
public:
    GenomeCov(const GCovArgs& a, GenomeFile& g) : _a(a), _g(g) {}
    void run();
private:
    const GCovArgs& _a;
    GenomeFile& _g;
    std::string _curChrom;
    CHRPOS _curSize = 0;
    // depth change events for current chromosome
    std::vector<std::pair<CHRPOS, int>> _events;
    std::map<long, unsigned long long> _genomeHist;
    std::set<std::string> _visited;
    std::string _out;

    void startChrom(const std::string& chrom);
    void addCoverage(CHRPOS s, CHRPOS e);
    void reportChrom();
    void flushOut() { if (!_out.empty()) { g_out.write(_out); _out.clear(); } }
    template <typename F> void forEachSegment(F fn);
};

void GenomeCov::startChrom(const std::string& chrom) {
    _curChrom = chrom;
    _curSize = _g.size(chrom);
    if (_curSize < 0) {
        fatal("Input error: Chromosome " + chrom + " found in your input file but not in your genome file.\n");
    }
    _events.clear();
    _visited.insert(chrom);
}

void GenomeCov::addCoverage(CHRPOS s, CHRPOS e) {
    if (s < 0) s = 0;
    if (e > _curSize) e = _curSize;
    if (s >= e) return;
    _events.push_back({s, 1});
    _events.push_back({e, -1});
}

// Iterate contiguous segments [s,e) of constant depth over [0,chromSize)
template <typename F>
void GenomeCov::forEachSegment(F fn) {
    std::sort(_events.begin(), _events.end());
    CHRPOS pos = 0;
    long depth = 0;
    size_t i = 0;
    while (i < _events.size()) {
        CHRPOS p = _events[i].first;
        if (p > pos) { fn(pos, p, depth); pos = p; }
        while (i < _events.size() && _events[i].first == p) { depth += _events[i].second; i++; }
    }
    if (pos < _curSize) fn(pos, _curSize, depth);
}

void GenomeCov::reportChrom() {
    if (_curChrom.empty()) return;
    const std::string& chrom = _curChrom;
    if (_a.eachBase || _a.eachBaseZero) {
        forEachSegment([&](CHRPOS s, CHRPOS e, long depth) {
            for (CHRPOS p = s; p < e; p++) {
                if (_a.eachBaseZero) {
                    if (depth == 0) continue;
                    _out += chrom; _out += '\t'; _out += toStr(p); _out += '\t'; _out += fmtFloat(depth * _a.scale); _out += '\n';
                } else {
                    _out += chrom; _out += '\t'; _out += toStr(p + 1); _out += '\t'; _out += fmtFloat(depth * _a.scale); _out += '\n';
                }
                if (_out.size() > 65536) flushOut();
            }
        });
    } else if (_a.bedGraph || _a.bedGraphAll) {
        forEachSegment([&](CHRPOS s, CHRPOS e, long depth) {
            if (depth == 0 && !_a.bedGraphAll) return;
            _out += chrom; _out += '\t'; _out += toStr(s); _out += '\t'; _out += toStr(e); _out += '\t';
            _out += fmtFloat(depth * _a.scale); _out += '\n';
            if (_out.size() > 65536) flushOut();
        });
    } else {
        std::map<long, unsigned long long> hist;
        forEachSegment([&](CHRPOS s, CHRPOS e, long depth) {
            long d = depth;
            if (_a.maxDepth != -1 && d > _a.maxDepth) d = _a.maxDepth;
            hist[d] += (unsigned long long)(e - s);
            _genomeHist[d] += (unsigned long long)(e - s);
        });
        for (auto& kv : hist) {
            _out += chrom; _out += '\t'; _out += toStr((CHRPOS)kv.first); _out += '\t'; _out += toStr((CHRPOS)kv.second);
            _out += '\t'; _out += toStr(_curSize); _out += '\t';
            _out += fmtFloat((double)kv.second / (double)_curSize); _out += '\n';
        }
    }
    flushOut();
}

void GenomeCov::run() {
    RecordFile rf;
    rf.open(_a.inFile);
    if (_a.trackline) {
        std::string tl = "track type=bedGraph";
        if (!_a.trackopts.empty()) { tl += " "; tl += _a.trackopts; }
        g_out.write(tl + "\n");
    }
    RecordPtr r;
    std::vector<Block> blocks;
    while ((r = rf.next())) {
        if (!_a.strand.empty()) {
            if (r->strand != _a.strand[0]) continue;
        }
        if (r->chrom != _curChrom) {
            if (_visited.count(r->chrom)) {
                fatal("Input error: Chromosome " + r->chrom + " found in non-sequential lines. This suggests that the input file is not sorted correctly.\n");
            }
            reportChrom();
            startChrom(r->chrom);
        }
        if (_a.only5 || _a.only3) {
            bool fivePrime = _a.only5;
            CHRPOS p;
            if (r->strand == '-') p = fivePrime ? r->end - 1 : r->start;
            else p = fivePrime ? r->start : r->end - 1;
            addCoverage(p, p + 1);
