        if (_a.only5 || _a.only3) {
            bool fivePrime = _a.only5;
            CHRPOS p;
            if (r->strand == '-') p = fivePrime ? r->end - 1 : r->start;
            else p = fivePrime ? r->start : r->end - 1;
            addCoverage(p, p + 1);
            continue;
        }
        r->getBlocks(blocks, _a.split);
        for (const Block& b : blocks) addCoverage(b.start, b.end);
    }
    reportChrom();
    // chromosomes without any records
    if (!_a.bedGraph && !_a.eachBaseZero) {
        for (const std::string& c : _g.chroms()) {
            if (_visited.count(c)) continue;
            _curChrom = c; _curSize = _g.size(c); _events.clear();
            reportChrom();
        }
    }
    if (!_a.eachBase && !_a.eachBaseZero && !_a.bedGraph && !_a.bedGraphAll) {
        CHRPOS gsize = _g.genomeSize();
        for (auto& kv : _genomeHist) {
            _out += "genome\t"; _out += toStr((CHRPOS)kv.first); _out += '\t'; _out += toStr((CHRPOS)kv.second); _out += '\t';
            _out += toStr(gsize); _out += '\t'; _out += fmtFloat((double)kv.second / (double)gsize); _out += '\n';
        }
        flushOut();
    }
}

