#include "context.h"
#include "tools.h"
#include <algorithm>
#include <map>
#include <sstream>

namespace {
struct Ivl { CHRPOS s, e; char strand; };

// Load and merge (bookended merge, optionally by strand) ; returns total merged length
static unsigned long long loadMerged(const std::string& fname, std::map<std::string, std::vector<Ivl>>& out,
                                     bool byStrand, std::vector<std::string>& chromOrder, bool checkSorted) {
    RecordFile rf;
    rf.open(fname);
    std::map<std::string, std::vector<Ivl>> raw;
    RecordPtr r;
    std::string lastChrom; CHRPOS lastStart = -1; std::vector<std::string> seen;
    while ((r = rf.next())) {
        if (checkSorted) {
            if (r->chrom == lastChrom) {
                if (r->start < lastStart) { std::string s; r->print(s); fatal("Error: Sorted input specified, but the file " + fname + " has the following out of order record\n" + s + "\n"); }
            } else {
                if (std::find(seen.begin(), seen.end(), r->chrom) != seen.end()) { std::string s; r->print(s); fatal("Error: Sorted input specified, but the file " + fname + " has the following out of order record\n" + s + "\n"); }
                seen.push_back(r->chrom);
                lastChrom = r->chrom;
            }
            lastStart = r->start;
        }
        if (!raw.count(r->chrom)) chromOrder.push_back(r->chrom);
        raw[r->chrom].push_back({r->start, r->end, r->strand});
    }
    unsigned long long total = 0;
    for (auto& kv : raw) {
        std::vector<Ivl>& v = kv.second;
        std::stable_sort(v.begin(), v.end(), [](const Ivl& a, const Ivl& b) { return a.s < b.s; });
        std::vector<Ivl>& m = out[kv.first];
        if (!byStrand) {
            for (const Ivl& iv : v) {
                if (!m.empty() && iv.s <= m.back().e) m.back().e = std::max(m.back().e, iv.e);
                else m.push_back(iv);
            }
        } else {
            std::map<char, Ivl*> cur;
            std::vector<Ivl> tmp;
            for (const Ivl& iv : v) {
                auto it = cur.find(iv.strand);
                if (it != cur.end() && iv.s <= it->second->e) it->second->e = std::max(it->second->e, iv.e);
                else { tmp.push_back(iv); cur[iv.strand] = &tmp.back(); // pointer may invalidate; rebuild
                    cur.clear(); for (Ivl& t : tmp) cur[t.strand] = &t; }
            }
            m = tmp;
            std::stable_sort(m.begin(), m.end(), [](const Ivl& a, const Ivl& b) { return a.s < b.s; });
        }
        for (const Ivl& iv : m) total += (unsigned long long)(iv.e - iv.s);
    }
    return total;
}
}

int jaccard_main(int argc, char** argv) {
    Context ctx("jaccard", argc, argv);
    ctx.parseCommon();
    ctx.finish();
    if (!ctx.haveA || !ctx.haveB) {
        if (ctx.haveA) ctx.error("query and database files not specified.");
        ctx.error("No input file given. Exiting.");
    }
    ctx.validate();
    bool byStrand = ctx.sameStrand || ctx.diffStrand;
    std::map<std::string, std::vector<Ivl>> A, B;
    std::vector<std::string> orderA, orderB;
    unsigned long long lenA = loadMerged(ctx.aFiles[0], A, byStrand, orderA, true);
    unsigned long long lenB = loadMerged(ctx.bFiles[0], B, byStrand, orderB, true);
    unsigned long long intersection = 0;
    unsigned long long nInt = 0;
    for (auto& kv : A) {
        auto it = B.find(kv.first);
        if (it == B.end()) continue;
        const std::vector<Ivl>& a = kv.second;
        const std::vector<Ivl>& b = it->second;
        size_t j = 0;
        for (const Ivl& x : a) {
            // advance j while b[j].e <= x.s
            while (j < b.size() && b[j].e <= x.s) j++;
            for (size_t k = j; k < b.size() && b[k].s < x.e; k++) {
                if (ctx.sameStrand && !(x.strand == b[k].strand && (x.strand == '+' || x.strand == '-'))) continue;
                if (ctx.diffStrand && !(x.strand != b[k].strand && (x.strand == '+' || x.strand == '-') && (b[k].strand == '+' || b[k].strand == '-'))) continue;
                CHRPOS ov = std::min(x.e, b[k].e) - std::max(x.s, b[k].s);
                if (ov <= 0) continue;
                CHRPOS aLen = x.e - x.s, bLen = b[k].e - b[k].s;
                bool okA = (double)ov / aLen >= ctx.fracA;
                bool okB = (double)ov / bLen >= ctx.fracB;
                bool ok = ctx.eitherFrac ? (okA || okB) : (okA && okB);
                if (!ok) continue;
                intersection += ov;
                nInt++;
            }
        }
    }
    unsigned long long unionVal = lenA + lenB - intersection;
    double jaccard = unionVal > 0 ? (double)intersection / (double)unionVal : 0.0;
    std::ostringstream os;
    os << "intersection\tunion\tjaccard\tn_intersections\n";
    os << intersection << "\t" << unionVal << "\t" << jaccard << "\t" << nInt << "\n";
    g_out.write(os.str());
    return 0;
}
