#include "tools.h"

int makewindows_main(int argc, char** argv) {
    std::string genomeFile, bedFile, idMode;
    CHRPOS size = 0, step = 0; long num = 0;
    bool haveSize = false, haveStep = false, haveNum = false, reverse = false, showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-g") { if (i + 1 < argc) genomeFile = argv[++i]; else showHelp = true; }
        else if (a == "-b") { if (i + 1 < argc) bedFile = argv[++i]; else showHelp = true; }
        else if (a == "-w") { if (i + 1 < argc) { size = strtoll(argv[++i], nullptr, 10); haveSize = true; } else showHelp = true; }
        else if (a == "-s") { if (i + 1 < argc) { step = strtoll(argv[++i], nullptr, 10); haveStep = true; } else showHelp = true; }
        else if (a == "-n") { if (i + 1 < argc) { num = atol(argv[++i]); haveNum = true; } else showHelp = true; }
        else if (a == "-reverse") reverse = true;
        else if (a == "-i") { if (i + 1 < argc) idMode = argv[++i]; else showHelp = true; }
        else { fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]); showHelp = true; }
    }
    if (showHelp) { printHelp("makewindows"); return 1; }
    bool fail = false;
    if (genomeFile.empty() && bedFile.empty()) { classicErrorMsg("Need -g (genome file) or -b (BED file) for interval source."); fail = true; }
    if (!genomeFile.empty() && !bedFile.empty()) { classicErrorMsg("Can't combine -g (genome file) with -b (BED file)."); fail = true; }
    if (!haveSize && !haveNum) { classicErrorMsg("Need -w (window size) or -n (number of windows)."); fail = true; }
    if (haveSize && haveNum) { classicErrorMsg("Can't combine -w (window size) with -n (number of windows)."); fail = true; }
    if (haveStep && !haveSize) { classicErrorMsg("Can't use -s (step) without -w (window size)."); fail = true; }
    if (!idMode.empty() && idMode != "src" && idMode != "winnum" && idMode != "srcwinnum") { classicErrorMsg("Invalid -i value. Must be src, winnum, or srcwinnum."); fail = true; }
    if (haveSize && size <= 0) { classicErrorMsg("Window size (-w) must be greater than zero."); fail = true; }
    if (haveNum && num <= 0) { classicErrorMsg("Number of windows (-n) must be greater than zero."); fail = true; }
    if (haveStep && step <= 0) { classicErrorMsg("Step size (-s) must be greater than zero."); fail = true; }
    if (fail) { printHelp("makewindows"); return 1; }
    if (!haveStep) step = size;

    std::string out;
    auto emit = [&](const std::string& chrom, CHRPOS s, CHRPOS e, const std::string& name, long winNum, long total) {
        out += chrom; out += '\t'; out += toStr(s); out += '\t'; out += toStr(e);
        long n = reverse ? (total - winNum + 1) : winNum;
        if (idMode == "src") { out += '\t'; out += name; }
        else if (idMode == "winnum") { out += '\t'; out += toStr((CHRPOS)n); }
        else if (idMode == "srcwinnum") { out += '\t'; out += name; out += '_'; out += toStr((CHRPOS)n); }
        out += '\n';
        if (out.size() > 65536) { g_out.write(out); out.clear(); }
    };
    auto makeWindows = [&](const std::string& chrom, CHRPOS start, CHRPOS end, const std::string& name) {
        std::vector<std::pair<CHRPOS, CHRPOS>> wins;
        if (haveSize) {
            for (CHRPOS s = start; s < end; s += step) {
                CHRPOS e = std::min(s + size, end);
                if (e > s) wins.push_back({s, e});
            }
        } else {
            CHRPOS len = end - start;
            CHRPOS wsize = len / num;
            if (len % num != 0) wsize++;
            if (wsize <= 0) wsize = 1;
            for (CHRPOS s = start; s < end; s += wsize) {
                CHRPOS e = std::min(s + wsize, end);
                wins.push_back({s, e});
            }
        }
        long total = (long)wins.size();
        for (size_t i = 0; i < wins.size(); i++) emit(chrom, wins[i].first, wins[i].second, name, (long)i + 1, total);
    };
    if (!genomeFile.empty()) {
        GenomeFile g; g.load(genomeFile);
        for (const std::string& c : g.chroms()) makeWindows(c, 0, g.size(c), c);
    } else {
        RecordFile rf; rf.open(bedFile);
        RecordPtr r;
        while ((r = rf.next())) makeWindows(r->chrom, r->start, r->end, r->name());
    }
    g_out.write(out);
    return 0;
}
