static std::string fmt7(double v) { char b[64]; snprintf(b, sizeof(b), "%0.7f", v); return b; }

int coverage_main(int argc, char** argv) {
    Context ctx("coverage", argc, argv);
    bool hist = false, perBase = false, counts = false, mean = false;
    for (size_t i = 0; i < ctx.args.size(); i++) {
        const std::string& a = ctx.args[i];
        if (a == "-hist") { hist = true; ctx.markUsed(i); }
        else if (a == "-d") { perBase = true; ctx.markUsed(i); }
        else if (a == "-counts") { counts = true; ctx.markUsed(i); }
        else if (a == "-mean") { mean = true; ctx.markUsed(i); }
    }
    ctx.parseCommon();
    ctx.finish();
    if (!ctx.haveA || !ctx.haveB) {
        if (ctx.haveA) ctx.error("query and database files not specified.");
        ctx.error("No input file given. Exiting.");
    }
    ctx.validate();

    RecordFile af; af.open(ctx.aFiles[0], 0);
    HitFinder hf(ctx); hf.loadDatabases();
    printHeaderIfRequested(ctx, af);

    std::vector<Hit> hits; std::string out; RecordPtr a;
    std::map<long, unsigned long long> finalHist; unsigned long long totalLen = 0;
    std::vector<int> depth; std::vector<Block> blocks;
    while ((a = af.next())) {
        hf.checkSortedA(*a, ctx.aFiles[0]);
        hf.find(*a, hits);
        CHRPOS qlen = a->length();
        depth.assign((size_t)std::max<CHRPOS>(qlen, 0), 0);
        for (const Hit& h : hits) {
            h.rec->getBlocks(blocks, ctx.split);
            for (const Block& b : blocks) {
                CHRPOS s = std::max(b.start, a->start), e = std::min(b.end, a->end);
                for (CHRPOS p = s; p < e; p++) depth[p - a->start]++;
            }
        }
        out.clear();
        if (counts) {
            a->print(out); out += '\t'; out += toStr((CHRPOS)hits.size()); out += '\n';
        } else if (perBase) {
            for (CHRPOS i = 0; i < qlen; i++) {
                a->print(out); out += '\t'; out += toStr(i + 1); out += '\t'; out += toStr((CHRPOS)depth[i]); out += '\n';
            }
        } else if (mean) {
            unsigned long long sum = 0; for (int d : depth) sum += d;
            std::ostringstream os; os << (qlen > 0 ? (float)sum / (float)qlen : 0.0f);
            a->print(out); out += '\t'; out += os.str(); out += '\n';
        } else if (hist) {
            std::map<long, unsigned long long> h;
            for (int d : depth) { h[d]++; finalHist[d]++; }
            for (auto& kv : h) {
                a->print(out); out += '\t'; out += toStr((CHRPOS)kv.first); out += '\t'; out += toStr((CHRPOS)kv.second);
                out += '\t'; out += toStr(qlen); out += '\t'; out += fmt7(qlen > 0 ? (float)kv.second / (float)qlen : 0.0); out += '\n';
            }
            totalLen += qlen;
        } else {
            unsigned long long nz = 0; for (int d : depth) if (d > 0) nz++;
            a->print(out); out += '\t'; out += toStr((CHRPOS)hits.size()); out += '\t'; out += toStr((CHRPOS)nz);
            out += '\t'; out += toStr(qlen); out += '\t'; out += fmt7(qlen > 0 ? (float)nz / (float)qlen : 0.0); out += '\n';
        }
        g_out.write(out);
    }
    if (hist) {
        out.clear();
        for (auto& kv : finalHist) {
            out += "all\t"; out += toStr((CHRPOS)kv.first); out += '\t'; out += toStr((CHRPOS)kv.second); out += '\t';
            out += toStr((CHRPOS)totalLen); out += '\t'; out += fmt7(totalLen > 0 ? (float)kv.second / (float)totalLen : 0.0); out += '\n';
        }
        g_out.write(out);
    }
    return 0;
}
