static std::string lower(const std::string& s) { std::string r = s; for (char& c : r) c = tolower(c); return r; }

int groupby_main(int argc, char** argv) {
    std::string inFile = "stdin", grpCols = "1,2,3", opCols, ops = "sum", delim = ",";
    bool full = false, inHeader = false, outHeader = false, ignoreCase = false, haveOpCols = false, showHelp = false;
