        if (a == "-i") { if (i + 1 < argc) inFile = argv[++i]; else showHelp = true; }
        else if (a == "-g" || a == "-grp") { if (i + 1 < argc) grpCols = argv[++i]; else showHelp = true; }
        else if (a == "-c" || a == "-opCols") { if (i + 1 < argc) { opCols = argv[++i]; haveOpCols = true; } else showHelp = true; }
        else if (a == "-o" || a == "-ops") { if (i + 1 < argc) ops = argv[++i]; else showHelp = true; }
        else if (a == "-full") full = true;
        else if (a == "-inheader") inHeader = true;
        else if (a == "-outheader") outHeader = true;
        else if (a == "-header") { inHeader = true; outHeader = true; }
        else if (a == "-ignorecase") ignoreCase = true;
        else if (a == "-prec") { if (i + 1 < argc) prec = atoi(argv[++i]); else showHelp = true; }
        else if (a == "-delim") { if (i + 1 < argc) delim = argv[++i]; else showHelp = true; }
        else { fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]); showHelp = true; }
    }
    if (showHelp) { printHelp("groupby"); return 1; }
    if (!haveOpCols) { classicErrorMsg("Need -c (opCols) and -o (ops)."); printHelp("groupby"); return 1; }
    std::vector<ColumnOp> colOps; std::string err;
    VectorOps::buildOps(opCols, ops, colOps, err);
    if (!err.empty()) { classicErrorMsg(err); printHelp("groupby"); return 1; }
    std::vector<std::string> gc; splitOn(grpCols, ',', gc);
    std::vector<int> groupCols; for (const std::string& s : gc) groupCols.push_back(atoi(s.c_str()));
    VectorOps vops(delim, prec);

    LineReader lr;
    if (!lr.open(inFile)) fatal("Error: Unable to open file " + inFile + ". Exiting.\n");
    std::string line; std::vector<std::string> f, headerFields;
    bool firstLine = true;
    std::vector<std::vector<std::string>> group;  // lines of current group
    std::string key, prevKey; bool haveGroup = false;
    std::string out; std::vector<std::string> vals;
    auto makeKey = [&](const std::vector<std::string>& flds) {
        std::string k;
        for (int c : groupCols) {
            if (c >= 1 && c <= (int)flds.size()) k += ignoreCase ? lower(flds[c - 1]) : flds[c - 1];
            k += '\x01';
        }
        return k;
    };
    auto flush = [&]() {
        if (!haveGroup) return;
        out.clear();
        const std::vector<std::string>& first = group[0];
        if (full) { for (size_t i = 0; i < first.size(); i++) { if (i) out += '\t'; out += first[i]; } }
        else {
            for (size_t i = 0; i < groupCols.size(); i++) {
                if (i) out += '\t';
                int c = groupCols[i];
                if (c >= 1 && c <= (int)first.size()) out += first[c - 1];
            }
        }
        for (const ColumnOp& co : colOps) {
            vals.clear();
            for (const std::vector<std::string>& g : group) {
                if (co.column < 1 || co.column > (int)g.size()) fatal("***** ERROR: requested column " + toStr(co.column) + " exceeds the number of columns in the input. Exiting. *****\n");
                vals.push_back(g[co.column - 1]);
            }
            out += '\t';
            out += vops.apply(co.op, vals, ".");
        }
        out += '\n';
        g_out.write(out);
        group.clear();
    };
    while (lr.getline(line)) {
        if (line.empty()) continue;
        if (firstLine && inHeader) {
            firstLine = false;
            splitTabs(line, headerFields);
            continue;
        }
        if (firstLine && outHeader) {
            // header names col_1 ...
        }
        firstLine = false;
        if (line[0] == '#') continue;
        splitTabs(line, f);
        key = makeKey(f);
        if (!haveGroup) {
            if (outHeader) {
                std::string h;
                auto colName = [&](int c) { if (!headerFields.empty() && c >= 1 && c <= (int)headerFields.size()) return headerFields[c - 1]; return std::string("col_") + toStr(c); };
                if (full) { for (size_t i = 0; i < f.size(); i++) { if (i) h += '\t'; h += colName((int)i + 1); } }
                else for (size_t i = 0; i < groupCols.size(); i++) { if (i) h += '\t'; h += colName(groupCols[i]); }
                for (const ColumnOp& co : colOps) { h += '\t'; h += colName(co.column) + "_" + co.op; }
                h += '\n';
                g_out.write(h);
                outHeader = false;
            }
            haveGroup = true; prevKey = key; group.push_back(f);
        } else if (key == prevKey) {
            group.push_back(f);
        } else {
            flush();
            prevKey = key; group.push_back(f);
        }
    }
    flush();
    return 0;
}
