    std::string inFile = "stdin", cols; bool haveCols = false, showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-i") { if (i + 1 < argc) inFile = argv[++i]; else showHelp = true; }
