        else { fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]); showHelp = true; }
    }
    if (showHelp) { printHelp("expand"); return 1; }
    if (!haveCols) { classicErrorMsg("Need -c (columns)."); printHelp("expand"); return 1; }
    std::vector<std::string> cs; splitOn(cols, ',', cs);
    std::vector<int> colIdx; for (const std::string& c : cs) colIdx.push_back(atoi(c.c_str()));
    LineReader lr; if (!lr.open(inFile)) fatal("Error: Unable to open file " + inFile + ". Exiting.\n");
    std::string line, out; std::vector<std::string> f;
    std::vector<std::vector<std::string>> parts;
    while (lr.getline(line)) {
        if (line.empty()) continue;
        if (line[0] == '#') { g_out.write(line + "\n"); continue; }
        splitTabs(line, f);
        parts.clear();
        size_t n = 0;
        for (size_t i = 0; i < colIdx.size(); i++) {
            int c = colIdx[i];
            parts.emplace_back();
            if (c >= 1 && c <= (int)f.size()) splitOn(f[c - 1], ',', parts.back());
            if (i == 0) n = parts.back().size();
            else if (parts.back().size() != n) fatal("Error: Column " + toStr(c) + " has a different number of values than the first expanded column.\n");
        }
        out.clear();
        for (size_t k = 0; k < n; k++) {
            for (size_t i = 0; i < f.size(); i++) {
                if (i) out += '\t';
                bool replaced = false;
                for (size_t j = 0; j < colIdx.size(); j++) if (colIdx[j] == (int)i + 1) { out += parts[j][k]; replaced = true; break; }
                if (!replaced) out += f[i];
            }
            out += '\n';
        }
        g_out.write(out);
    }
    return 0;
}

