        else if (a == "-allowBeyondChromEnd") allowBeyond = true;
        else { fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]); showHelp = true; }
    }
    if (showHelp) { printHelp("shuffle"); return 1; }
    if (inFile.empty() || genomeFile.empty()) { classicErrorMsg("Need both a BED (-i) and a genome (-g) file."); printHelp("shuffle"); return 1; }
    if (haveIncl && haveExcl) { classicErrorMsg("Cannot use both -incl and -excl."); printHelp("shuffle"); return 1; }
    (void)bedpe;
    GenomeFile g; g.load(genomeFile);
    if (haveSeed) srand(seed); else srand((unsigned)time(0) + (unsigned)getpid());
    BinIndex excl, placed;
    std::vector<RecordPtr> inclRecs;
    if (haveExcl) { std::vector<RecordPtr> v; readAllRecords(exclFile, v); for (auto& r : v) excl.add(r); }
    if (haveIncl) { readAllRecords(inclFile, inclRecs); chromFirst = false; }
    CHRPOS gsize = g.genomeSize();
    RecordFile rf; rf.open(inFile);
    RecordPtr r; std::string out; std::vector<RecordPtr> hits;
    while ((r = rf.next())) {
        CHRPOS len = r->length();
        std::string chrom = r->chrom; CHRPOS start = r->start, end = r->end;
        auto choose = [&]() {
            if (haveIncl && !inclRecs.empty()) {
                const RecordPtr& iv = inclRecs[rand() % inclRecs.size()];
                chrom = iv->chrom;
                CHRPOS span = iv->length();
                start = iv->start + (span > 0 ? rand() % span : 0);
            } else if (sameChrom) {
                CHRPOS cs = g.size(chrom);
                if (cs < 0) fatal("***** ERROR: chromosome " + chrom + " is not found in the genome file. Exiting. *****\n");
                CHRPOS range = allowBeyond ? cs : std::max<CHRPOS>(cs - len, 1);
                start = bigRand() % range;
            } else if (chromFirst) {
                int ci = rand() % (int)g.chroms().size();
                chrom = g.chroms()[ci];
                CHRPOS cs = g.size(chrom);
                CHRPOS range = allowBeyond ? cs : std::max<CHRPOS>(cs - len, 1);
                start = bigRand() % range;
            } else {
                CHRPOS pos = bigRand() % gsize; CHRPOS off;
                int ci = projectOnGenome(g, pos, off);
                chrom = g.chroms()[ci]; start = off;
            }
            end = start + len;
