            if (haveExcl) {
                hits.clear(); excl.query(chrom, start, end, hits);
                for (auto& h : hits) {
                    CHRPOS ov = std::min(end, h->end) - std::max(start, h->start);
                    if (ov > 0 && (double)ov / (double)std::max<CHRPOS>(len, 1) >= overlapFrac) { bad = true; break; }
                }
            }
            if (!bad && noOverlapping) { hits.clear(); placed.query(chrom, start, end, hits); if (!hits.empty()) bad = true; }
            if (!bad) { ok = true; break; }
        }
        if (!ok) {
            fprintf(stderr, "Error, line %ld: tried %d potential loci for entry, but could not avoid excluded regions.  Ignoring entry and moving on.\n", r->lineNum, maxTries);
            continue;
        }
        if (noOverlapping) { RecordPtr p = std::make_shared<Record>(*r); p->chrom = chrom; p->start = start; p->end = end; placed.add(p); }
        out.clear();
        std::vector<std::string> f = r->f;
