        else { f[0] = chrom; f[1] = toStr(start); f[2] = toStr(end); }
        for (size_t i = 0; i < f.size(); i++) { if (i) out += '\t'; out += f[i]; }
        out += '\n';
        g_out.write(out);
    }
    return 0;
}

