// project a genome-wide position onto (chrom index, offset)
static int projectOnGenome(const GenomeFile& g, CHRPOS pos, CHRPOS& offset) {
    const std::vector<CHRPOS>& starts = g.starts();
    int lo = 0, hi = (int)starts.size() - 1, idx = 0;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (starts[mid] <= pos) { idx = mid; lo = mid + 1; } else hi = mid - 1;
    }
    offset = pos - starts[idx];
    return idx;
}

