#include "classic.h"
#include "tools.h"
#include <map>
#include <set>
#include <algorithm>

namespace {
struct MIvl { CHRPOS s, e; std::string val; int file; };

struct MultiArgs {
    std::vector<std::string> files, names;
    std::string genomeFile, filler = "0";
    bool header = false, empty = false, cluster = false;
};

static bool parseMultiArgs(const char* tool, int argc, char** argv, MultiArgs& m) {
    bool showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-i") {
            while (i + 1 < argc && argv[i + 1][0] != '-') m.files.push_back(argv[++i]);
        } else if (a == "-names") {
            while (i + 1 < argc && argv[i + 1][0] != '-') m.names.push_back(argv[++i]);
        } else if (a == "-g") { if (i + 1 < argc) m.genomeFile = argv[++i]; else showHelp = true; }
        else if (a == "-filler") { if (i + 1 < argc) m.filler = argv[++i]; else showHelp = true; }
        else if (a == "-header") m.header = true;
        else if (a == "-empty") m.empty = true;
        else if (a == "-cluster") m.cluster = true;
        else if (a == "-examples") { printHelp(tool); exit(0); }
        else { fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]); showHelp = true; }
    }
    if (showHelp) { printHelp(tool); exit(1); }
    return true;
}

// Core sweep shared by multiinter and unionbedg
static void multiSweep(const MultiArgs& m, bool unionMode) {
    size_t nFiles = m.files.size();
    std::map<std::string, std::vector<MIvl>> byChrom;
    std::vector<std::string> chromOrder;
    for (size_t fi = 0; fi < nFiles; fi++) {
        RecordFile rf; rf.open(m.files[fi], (int)fi);
        RecordPtr r;
        while ((r = rf.next())) {
            if (!byChrom.count(r->chrom)) chromOrder.push_back(r->chrom);
            MIvl iv; iv.s = r->start; iv.e = r->end; iv.file = (int)fi;
            if (unionMode) iv.val = r->f.size() > 3 ? r->f[3] : m.filler;
            byChrom[r->chrom].push_back(iv);
        }
    }
    GenomeFile g; bool haveGenome = !m.genomeFile.empty();
    if (haveGenome) g.load(m.genomeFile);
    std::vector<std::string> chroms;
    if (haveGenome) {
        chroms = g.chroms();
        for (const std::string& c : chromOrder) if (!g.hasChrom(c)) chroms.push_back(c);
    } else {
        chroms = chromOrder;
        std::sort(chroms.begin(), chroms.end());
    }
    std::string out;
    if (m.header) {
        out = "chrom\tstart\tend";
        if (!unionMode) out += "\tnum\tlist";
        for (size_t fi = 0; fi < nFiles; fi++) { out += '\t'; out += (fi < m.names.size()) ? m.names[fi] : m.files[fi]; }
        out += '\n';
        g_out.write(out); out.clear();
    }
    for (const std::string& chrom : chroms) {
        std::vector<MIvl> ivls;
        auto it = byChrom.find(chrom);
        if (it != byChrom.end()) ivls = it->second;
        std::stable_sort(ivls.begin(), ivls.end(), [](const MIvl& a, const MIvl& b) { return a.s < b.s; });
        std::vector<CHRPOS> bounds;
