cat > /workspace/src/fasta.cpp <<'EOF'
#include "fasta.h"
#include "record.h"

bool Fasta::load(const std::string& fname, bool fullHeader) {
    LineReader lr;
    if (!lr.open(fname)) return false;
    std::string line;
    bool firstSeqLine = true;
    while (lr.getline(line)) {
        if (line.empty()) continue;
        if (line[0] == '>') {
            std::string hdr = line.substr(1);
            std::string name = hdr;
            if (!fullHeader) {
                size_t p = name.find_first_of(" \t");
                if (p != std::string::npos) name = name.substr(0, p);
            }
            _idx[name] = _names.size();
            _names.push_back(name);
            _headers.push_back(hdr);
            _seqs.emplace_back();
            firstSeqLine = true;
        } else if (!_seqs.empty()) {
            if (firstSeqLine && _lineWidth == 0) _lineWidth = (int)line.size();
            firstSeqLine = false;
            _seqs.back().append(line);
        }
    }
    return true;
}

std::string reverseComplement(const std::string& s, bool rna) {
    std::string r(s.rbegin(), s.rend());
    for (char& c : r) {
        switch (c) {
            case 'A': c = rna ? 'U' : 'T'; break;
            case 'T': c = 'A'; break;
            case 'U': c = 'A'; break;
            case 'C': c = 'G'; break;
            case 'G': c = 'C'; break;
            case 'a': c = rna ? 'u' : 't'; break;
            case 't': c = 'a'; break;
            case 'u': c = 'a'; break;
            case 'c': c = 'g'; break;
            case 'g': c = 'c'; break;
            case 'N': c = 'N'; break;
            case 'n': c = 'n'; break;
            case 'R': c = 'Y'; break; case 'Y': c = 'R'; break;
            case 'r': c = 'y'; break; case 'y': c = 'r'; break;
            case 'K': c = 'M'; break; case 'M': c = 'K'; break;
