            if (!pat.empty()) { size_t p = 0; while ((p = hay.find(pat, p)) != std::string::npos) { count++; p += 1; } }
            out += '\t'; out += toStr((CHRPOS)count);
        }
        out += '\n';
        g_out.write(out);
    }
    return 0;
}
