// ---------------- fisher ----------------
namespace {
static double lfact(long n) { return lgamma((double)n + 1.0); }
// hypergeometric pmf: P(X = k) with population N, K successes, n draws
static double hyperLogPmf(long k, long N, long K, long n) {
    return lfact(K) - lfact(k) - lfact(K - k) + lfact(N - K) - lfact(n - k) - lfact(N - K - n + k) - lfact(N) + lfact(n) + lfact(N - n);
}
}

int fisher_main(int argc, char** argv) {
    Context ctx("fisher", argc, argv);
    bool mergeFirst = false;
    for (size_t i = 0; i < ctx.args.size(); i++) if (ctx.args[i] == "-m") { mergeFirst = true; ctx.markUsed(i); }
    ctx.parseCommon();
    ctx.finish();
    if (!ctx.haveA || !ctx.haveB) {
        if (ctx.haveA) ctx.error("query and database files not specified.");
        ctx.error("No input file given. Exiting.");
    }
    if (ctx.genomeFile.empty()) ctx.error("fisher requires a genome file (-g).");
    ctx.validate();
    GenomeFile g; g.load(ctx.genomeFile);
    auto load = [&](const std::string& f, std::map<std::string, std::vector<std::pair<CHRPOS, CHRPOS>>>& out, long& count, unsigned long long& len) {
        std::vector<RecordPtr> recs; readAllRecords(f, recs);
        for (const RecordPtr& r : recs) out[r->chrom].push_back({r->start, r->end});
        count = 0; len = 0;
        for (auto& kv : out) {
            std::sort(kv.second.begin(), kv.second.end());
            if (mergeFirst) {
                std::vector<std::pair<CHRPOS, CHRPOS>> m;
                for (auto& iv : kv.second) { if (!m.empty() && iv.first <= m.back().second) m.back().second = std::max(m.back().second, iv.second); else m.push_back(iv); }
                kv.second = m;
            }
            count += (long)kv.second.size();
            for (auto& iv : kv.second) len += (unsigned long long)(iv.second - iv.first);
        }
    };
    std::map<std::string, std::vector<std::pair<CHRPOS, CHRPOS>>> A, B;
    long nA, nB; unsigned long long lenA, lenB;
    load(ctx.aFiles[0], A, nA, lenA);
    load(ctx.bFiles[0], B, nB, lenB);
    long overlaps = 0;
    for (auto& kv : A) {
        auto it = B.find(kv.first); if (it == B.end()) continue;
        const auto& b = it->second; size_t j = 0;
        for (auto& x : kv.second) {
            while (j < b.size() && b[j].second <= x.first) j++;
            for (size_t k = j; k < b.size() && b[k].first < x.second; k++) if (std::min(x.second, b[k].second) > std::max(x.first, b[k].first)) overlaps++;
        }
    }
    double genomeSize = (double)g.genomeSize();
    double meanLen = (nA + nB) > 0 ? (double)(lenA + lenB) / (double)(nA + nB) : 1.0;
    long possible = (long)(genomeSize / meanLen);
    long n11 = overlaps, n12 = nA - overlaps, n21 = nB - overlaps, n22 = possible - n11 - n12 - n21;
    if (n22 < 0) n22 = 0;
    long N = n11 + n12 + n21 + n22, K = n11 + n12, n = n11 + n21;
    // Fisher exact
    long kmin = std::max(0L, K + n - N), kmax = std::min(K, n);
    double pObs = hyperLogPmf(n11, N, K, n);
    double left = 0, right = 0, two = 0;
    for (long k = kmin; k <= kmax; k++) {
        double lp = hyperLogPmf(k, N, K, n);
        double p = exp(lp);
        if (k <= n11) left += p;
        if (k >= n11) right += p;
        if (lp <= pObs + 1e-7 * fabs(pObs)) two += p;
    }
    left = std::min(left, 1.0); right = std::min(right, 1.0); two = std::min(two, 1.0);
    double ratio = (n12 > 0 && n21 > 0) ? ((double)n11 * (double)n22) / ((double)n12 * (double)n21) : INFINITY;
    std::string out;
    char buf[512];
    snprintf(buf, sizeof(buf), "# Number of query intervals: %ld\n# Number of db intervals: %ld\n# Number of overlaps: %ld\n# Number of possible intervals (estimated): %ld\n", nA, nB, overlaps, possible);
    out += buf;
    snprintf(buf, sizeof(buf), "# phyper(%ld - 1, %ld, %ld - %ld, %ld, lower.tail=F)\n", n11, nA, possible, nA, nB);
    out += buf;
    out += "# Contingency Table Of Counts\n";
    out += "#_________________________________________\n";
    out += "#           |  in -b       | not in -b    |\n";
    snprintf(buf, sizeof(buf), "#     in -a | %-12ld | %-12ld |\n", n11, n12); out += buf;
    snprintf(buf, sizeof(buf), "# not in -a | %-12ld | %-12ld |\n", n21, n22); out += buf;
    out += "#_________________________________________\n";
    out += "# p-values for fisher's exact test\n";
    out += "left\tright\ttwo-tail\tratio\n";
    snprintf(buf, sizeof(buf), "%.5g\t%.5g\t%.5g\t%.3f\n", left, right, two, ratio);
    out += buf;
    g_out.write(out);
    return 0;
}

// ---------------- summary ----------------
int summary_main(int argc, char** argv) {
    Context ctx("summary", argc, argv);
    ctx.parseCommon();
    ctx.finish();
    if (!ctx.haveA) ctx.error("No input file given. Exiting.");
    if (ctx.genomeFile.empty()) ctx.error("no -g genome file provided.");
    GenomeFile g; g.load(ctx.genomeFile);
    struct Stat { long n = 0; unsigned long long bp = 0; CHRPOS mn = -1, mx = -1; };
    std::map<std::string, Stat> stats; Stat all;
    RecordFile rf; rf.open(ctx.aFiles[0]);
    RecordPtr r;
    while ((r = rf.next())) {
        Stat& s = stats[r->chrom];
        CHRPOS len = r->length();
        s.n++; s.bp += len; if (s.mn < 0 || len < s.mn) s.mn = len; if (len > s.mx) s.mx = len;
        all.n++; all.bp += len; if (all.mn < 0 || len < all.mn) all.mn = len; if (len > all.mx) all.mx = len;
    }
    std::string out = "chrom\tchrom_length\tnum_ivls\ttotal_ivl_bp\tchrom_frac_genome\tfrac_all_ivls\tfrac_all_bp\tmin\tmax\tmean\n";
    double gsize = (double)g.genomeSize();
    auto row = [&](const std::string& chrom, CHRPOS clen, const Stat& s) {
        std::ostringstream os;
        os << chrom << '\t' << clen << '\t' << s.n << '\t' << s.bp << '\t' << (gsize > 0 ? (double)clen / gsize : 0.0) << '\t'
           << (all.n > 0 ? (double)s.n / (double)all.n : 0.0) << '\t' << (all.bp > 0 ? (double)s.bp / (double)all.bp : 0.0) << '\t'
           << (s.n ? s.mn : 0) << '\t' << (s.n ? s.mx : 0) << '\t' << (s.n ? (double)s.bp / (double)s.n : 0.0) << '\n';
        out += os.str();
    };
    for (const std::string& c : g.chroms()) {
        auto it = stats.find(c);
        if (it == stats.end()) continue;
        row(c, g.size(c), it->second);
    }
    row("all", g.genomeSize(), all);
    g_out.write(out);
    return 0;
}
