#include "classic.h"
#include "binindex.h"
#include "tools.h"
#include <algorithm>

static void readBedpe(const std::string& fname, std::vector<RecordPtr>& recs) {
    RecordFile rf; rf.setBedpe(true); rf.open(fname);
    RecordPtr r; while ((r = rf.next())) recs.push_back(r);
}

static bool strandMatch(char a, char b, bool same, bool diff) {
    if (same) return (a == '+' || a == '-') && a == b;
    if (diff) return (a == '+' || a == '-') && (b == '+' || b == '-') && a != b;
    return true;
}

int pairtobed_main(int argc, char** argv) {
    std::string aFile, bFile, type = "either"; double frac = 1e-9; bool sameStrand = false, diffStrand = false, showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-a" || a == "-abam") { if (i + 1 < argc) aFile = argv[++i]; else showHelp = true; }
        else if (a == "-b") { if (i + 1 < argc) bFile = argv[++i]; else showHelp = true; }
        else if (a == "-f") { if (i + 1 < argc) frac = atof(argv[++i]); else showHelp = true; }
        else if (a == "-s") sameStrand = true;
        else if (a == "-S") diffStrand = true;
        else if (a == "-type") { if (i + 1 < argc) type = argv[++i]; else showHelp = true; }
        else if (a == "-ubam" || a == "-bedpe" || a == "-ed") {}
        else { fprintf(stderr, "*****ERROR: Unrecognized parameter: %s *****\n\n", argv[i]); showHelp = true; }
    }
    if (showHelp) { printHelp("pairtobed"); return 1; }
    if (aFile.empty() || bFile.empty()) { classicErrorMsg("Need -a and -b files."); printHelp("pairtobed"); return 1; }
    static const char* types[] = {"either", "neither", "both", "xor", "notboth", "ispan", "ospan", "notispan", "notospan", nullptr};
    bool ok = false; for (int i = 0; types[i]; i++) if (type == types[i]) ok = true;
    if (!ok) { classicErrorMsg("Request \"either\", \"neither\", \"both\", \"xor\", \"notboth\", \"ispan\", \"ospan\", \"notispan\", or \"notospan\" for -type."); printHelp("pairtobed"); return 1; }
    BinIndex idx; { std::vector<RecordPtr> v; readAllRecords(bFile, v); for (auto& r : v) idx.add(r); }
    std::vector<RecordPtr> pairs; readBedpe(aFile, pairs);
    std::string out; std::vector<RecordPtr> h1, h2, q1, q2;
    auto qualHits = [&](const std::string& chrom, CHRPOS s, CHRPOS e, char strand, std::vector<RecordPtr>& hits, std::vector<RecordPtr>& qual) {
        hits.clear(); qual.clear();
        idx.query(chrom, s, e, hits);
        for (auto& b : hits) {
            CHRPOS ov = std::min(e, b->end) - std::max(s, b->start);
            if (ov <= 0) continue;
            if ((double)ov / (double)std::max<CHRPOS>(e - s, 1) < frac) continue;
            if (!strandMatch(strand, b->strand, sameStrand, diffStrand)) continue;
            qual.push_back(b);
        }
    };
    for (const RecordPtr& p : pairs) {
        out.clear();
        if (type == "ispan" || type == "ospan" || type == "notispan" || type == "notospan") {
            if (p->chrom != p->chrom2) continue;
            CHRPOS s, e;
            if (type == "ispan" || type == "notispan") { s = p->end; e = p->start2; } else { s = p->start; e = p->end2; }
            if (e < s) std::swap(s, e);
            qualHits(p->chrom, s, e, '.', h1, q1);
            if (type == "ispan" || type == "ospan") { for (auto& b : q1) { p->print(out); out += '\t'; b->print(out); out += '\n'; } }
            else if (q1.empty()) { p->print(out); out += '\n'; }
        } else {
            qualHits(p->chrom, p->start, p->end, p->strand, h1, q1);
            qualHits(p->chrom2, p->start2, p->end2, p->strand2, h2, q2);
            bool e1 = !q1.empty(), e2 = !q2.empty();
            if (type == "either") { for (auto& b : q1) { p->print(out); out += '\t'; b->print(out); out += '\n'; } for (auto& b : q2) { p->print(out); out += '\t'; b->print(out); out += '\n'; } }
            else if (type == "neither") { if (!e1 && !e2) { p->print(out); out += '\n'; } }
            else if (type == "both") { if (e1 && e2) { for (auto& b : q1) { p->print(out); out += '\t'; b->print(out); out += '\n'; } for (auto& b : q2) { p->print(out); out += '\t'; b->print(out); out += '\n'; } } }
            else if (type == "xor") { if (e1 != e2) { for (auto& b : q1) { p->print(out); out += '\t'; b->print(out); out += '\n'; } for (auto& b : q2) { p->print(out); out += '\t'; b->print(out); out += '\n'; } } }
            else if (type == "notboth") { if (!(e1 && e2)) { p->print(out); out += '\n'; } }
        }
        if (!out.empty()) g_out.write(out);
    }
    return 0;
}

int pairtopair_main(int argc, char** argv) {
