    BinIndex idx1, idx2;
    for (auto& b : B) {
        RecordPtr e1 = std::make_shared<Record>(*b); e1->chrom = b->chrom; e1->start = b->start; e1->end = b->end; idx1.add(e1);
        RecordPtr e2 = std::make_shared<Record>(*b); e2->chrom = b->chrom2; e2->start = b->start2; e2->end = b->end2; idx2.add(e2);
    }
    (void)idx2;
    auto overlapsEnd = [&](const std::string& chrom, CHRPOS s, CHRPOS e, char strand, const std::string& bchrom, CHRPOS bs, CHRPOS be, char bstrand) {
        if (chrom != bchrom) return false;
        CHRPOS ov = std::min(e, be) - std::max(s, bs);
        if (ov <= 0) return false;
        if ((double)ov / (double)std::max<CHRPOS>(e - s, 1) < frac) return false;
        if (!ignoreStrand && strand != bstrand) return false;
        return true;
    };
    std::string out;
    for (auto& a : A) {
        CHRPOS s1 = a->start, e1 = a->end, s2 = a->start2, e2 = a->end2;
        if (strandSlop) {
            if (a->strand == '+') e1 += slop; else s1 -= slop;
            if (a->strand2 == '+') e2 += slop; else s2 -= slop;
        } else { s1 -= slop; e1 += slop; s2 -= slop; e2 += slop; }
        if (s1 < 0) s1 = 0; if (s2 < 0) s2 = 0;
        out.clear();
        bool anyBoth = false, anyEither = false;
        for (auto& b : B) {
            if (reqDiffNames && a->name() == b->name()) continue;
            bool o11 = overlapsEnd(a->chrom, s1, e1, a->strand, b->chrom, b->start, b->end, b->strand);
            bool o22 = overlapsEnd(a->chrom2, s2, e2, a->strand2, b->chrom2, b->start2, b->end2, b->strand2);
            bool o12 = overlapsEnd(a->chrom, s1, e1, a->strand, b->chrom2, b->start2, b->end2, b->strand2);
            bool o21 = overlapsEnd(a->chrom2, s2, e2, a->strand2, b->chrom, b->start, b->end, b->strand);
            bool both = (o11 && o22) || (o12 && o21);
            bool either = o11 || o22 || o12 || o21;
            if (both) anyBoth = true;
            if (either) anyEither = true;
            if (type == "both" && both) { a->print(out); out += '\t'; b->print(out); out += '\n'; }
            else if (type == "either" && either) { a->print(out); out += '\t'; b->print(out); out += '\n'; }
        }
        if (type == "neither" && !anyEither) { a->print(out); out += '\n'; }
        if (type == "notboth" && !anyBoth) { a->print(out); out += '\n'; }
        if (!out.empty()) g_out.write(out);
    }
    return 0;
}
