int split_main(int argc, char** argv) {
    std::string inFile, prefix = "_split", algo = "size"; long n = 0; bool showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-i" || a == "--input") { if (i + 1 < argc) inFile = argv[++i]; else showHelp = true; }
        else if (a == "-n" || a == "--number") { if (i + 1 < argc) n = atol(argv[++i]); else showHelp = true; }
