    }
    if (showHelp) { printHelp("pairtopair"); return 1; }
    if (aFile.empty() || bFile.empty()) { classicErrorMsg("Need -a and -b files."); printHelp("pairtopair"); return 1; }
    if (type != "neither" && type != "either" && type != "both" && type != "notboth") { classicErrorMsg("Request \"either\", \"neither\", \"both\", or \"notboth\" for -type."); printHelp("pairtopair"); return 1; }
    std::vector<RecordPtr> A, B; readBedpe(aFile, A); readBedpe(bFile, B);
