#include "classic.h"
#include "tools.h"
#include <algorithm>

int split_main(int argc, char** argv) {
    std::string inFile, prefix = "_split", algo = "size"; long n = 0; bool showHelp = false;
    for (int i = 2; i < argc; i++) {
        std::string a = argv[i];
        if (a == "-i" || a == "--input") { if (i + 1 < argc) inFile = argv[++i]; else showHelp = true; }
        else if (a == "-n" || a == "--number") { if (i + 1 < argc) n = atol(argv[++i]); else showHelp = true; }
        else if (a == "-p" || a == "--prefix") { if (i + 1 < argc) prefix = argv[++i]; else showHelp = true; }
        else if (a == "-a" || a == "--algorithm") { if (i + 1 < argc) algo = argv[++i]; else showHelp = true; }
        else if (a == "-v" || a == "--version") { printf("bedtools 9560abc\n"); return 0; }
        else { fprintf(stderr, "Error: unknown option: %s\n", argv[i]); showHelp = true; }
    }
    if (showHelp) { printHelp("split"); return 1; }
    if (n <= 0) { fprintf(stderr, "Error: num_chunks==0.\n\n"); printHelp("split"); return 1; }
    if (inFile.empty()) { fprintf(stderr, "Error: input file undefined.\n\n"); printHelp("split"); return 1; }
    if (algo != "size" && algo != "simple") { fprintf(stderr, "Error: unknown algorithm: %s\n\n", algo.c_str()); printHelp("split"); return 1; }
    std::vector<RecordPtr> recs; readAllRecords(inFile, recs);
    std::vector<std::vector<RecordPtr>> chunks(n);
    std::vector<unsigned long long> sizes(n, 0);
    if (algo == "simple") {
        for (size_t i = 0; i < recs.size(); i++) { chunks[i % n].push_back(recs[i]); sizes[i % n] += recs[i]->length(); }
    } else {
        // largest-first greedy: assign each record to the chunk with the smallest total size
        std::vector<RecordPtr> sorted = recs;
        std::stable_sort(sorted.begin(), sorted.end(), [](const RecordPtr& a, const RecordPtr& b) { return a->length() > b->length(); });
        for (const RecordPtr& r : sorted) {
            size_t best = 0;
            for (size_t k = 1; k < (size_t)n; k++) if (sizes[k] < sizes[best]) best = k;
            chunks[best].push_back(r); sizes[best] += r->length();
        }
    }
    std::string out;
    for (long k = 0; k < n; k++) {
        char name[4096]; snprintf(name, sizeof(name), "%s.%05ld.bed", prefix.c_str(), k + 1);
        FILE* fo = fopen(name, "w");
        if (!fo) fatal(std::string("Error: cannot open ") + name + " for writing.\n");
        std::string buf;
        for (const RecordPtr& r : chunks[k]) { r->print(buf); buf += '\n'; }
        fwrite(buf.data(), 1, buf.size(), fo); fclose(fo);
        out += name; out += '\t'; out += toStr((CHRPOS)sizes[k]); out += '\t'; out += toStr((CHRPOS)chunks[k].size()); out += '\n';
    }
    g_out.write(out);
    return 0;
}

int bamtool_main(int argc, char** argv) {
    (void)argc;
    fprintf(stderr, "***** ERROR: BAM/CRAM support is not available in this build of bedtools (%s). *****\n", argv[1]);
    return 1;
}
