                int ci = projectOnGenome(g, pos, off);
                chrom = g.chroms()[ci]; start = off; cs = g.size(chrom);
            }
            end = start + len;
            return cs;
        };
        auto choose = [&]() {
            CHRPOS cs = chooseOnce();
            if (!allowBeyond) { while (end > cs) cs = chooseOnce(); }
            else if (end > cs) end = cs;
        };
        choose();
