                    }
                }
                if (noOverlapping) { hits.clear(); placed.query(chrom, start, end, hits); if (!hits.empty()) return true; }
                return false;
            };
            int tries = 0;
            bool bad = overlaps();
            while (bad && tries <= maxTries) { choose(); bad = overlaps(); tries++; }
            if (tries > maxTries) {
                fprintf(stderr, "Error, line %ld: tried %d potential loci for entry, but could not avoid excluded regions.  Ignoring entry and moving on.\\n", r->lineNum, maxTries);
